def get_weibo_hotspots(limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return _now_utc().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _clamp_int(n, lo=None, hi=None):
        try:
            x = int(n)
        except Exception:
            return None
        if lo is not None and x < lo:
            x = lo
        if hi is not None and x > hi:
            x = hi
        return x

    start = time.time()
    now = _now_utc()

    # Validate inputs: JSON-Schema additionalProperties=false is enforced by signature; only validate limit.
    req_params = {}
    limit_val = None
    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be a number greater than 0")
        if not (limit > 0):
            return _err("VALIDATION_ERROR", "limit must be greater than 0")
        # store request param as provided
        req_params["limit"] = limit
        limit_val = int(limit) if float(limit).is_integer() else int(limit)  # floor-ish like typical servers
        if limit_val <= 0:
            return _err("VALIDATION_ERROR", "limit must be greater than 0")

    # Load stores
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    sources = _load("data_sources.json")
    snaps = _load("fetch_snapshots.json")
    invs = _load("tool_invocations.json")

    # Resolve ambient auth: find any active client+key combination that can serve request.
    active_clients = {c.get("id"): c for c in clients if c.get("status") == "active"}
    active_keys = [k for k in keys if k.get("status") == "active" and k.get("client_id") in active_clients]

    # Create invocation row early (received), then update status.
    inv_id = _gen_id("invk")
    base_inv = {
        "id": inv_id,
        "client_id": None,
        "api_key_id": None,
        "tool_name": "get-weibo-hotspots",
        "request_params": req_params,
        "limit": float(limit) if limit is not None else None,
        "horoscope_type": None,
        "horoscope_time": None,
        "sentence_random": None,
        "status": "received",
        "snapshot_ids": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "invoked_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    chosen_key = None
    chosen_client = None
    if active_keys:
        chosen_key = active_keys[0]
        chosen_client = active_clients.get(chosen_key.get("client_id"))
        base_inv["client_id"] = chosen_client.get("id") if chosen_client else None
        base_inv["api_key_id"] = chosen_key.get("id")
    else:
        # record failed invocation (no auth)
        base_inv["status"] = "failed"
        base_inv["error_code"] = "UNAUTHORIZED"
        base_inv["error_message"] = "No active API key/client available for this request"
        base_inv["latency_ms"] = int((time.time() - start) * 1000)
        base_inv["updated_at"] = _iso(_now_utc())
        invs.append(base_inv)
        _save("tool_invocations.json", invs)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Enforce rate limit and quota for chosen client, otherwise try other active keys that may pass.
    def _count_requests_in_window(client_id, window_seconds):
        cutoff = now - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for r in invs:
            if r.get("client_id") != client_id:
                continue
            t = _parse_dt(r.get("invoked_at"))
            if t is None:
                continue
            if t >= cutoff:
                cnt += 1
        return cnt

    def _count_requests_today(client_id, tz_name):
        # Use client's timezone if available; if invalid, fall back to UTC.
        try:
            tz = datetime.timezone.utc
            if isinstance(tz_name, str) and tz_name:
                try:
                    tz = datetime.ZoneInfo(tz_name)
                except Exception:
                    tz = datetime.timezone.utc
        except Exception:
            tz = datetime.timezone.utc
        local_now = now.astimezone(tz)
        day_start_local = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
        day_start = day_start_local.astimezone(datetime.timezone.utc)
        cnt = 0
        for r in invs:
            if r.get("client_id") != client_id:
                continue
            t = _parse_dt(r.get("invoked_at"))
            if t is None:
                continue
            if t >= day_start and t <= now:
                cnt += 1
        return cnt

    def _pick_auth_context():
        # pick a key/client that satisfies rate/quota now
        for k in active_keys:
            c = active_clients.get(k.get("client_id"))
            if not c:
                continue
            rpm = c.get("rate_limit_rpm")
            dq = c.get("daily_quota_requests")
            if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
                continue
            if not isinstance(dq, int) or not (dq == -1 or dq >= 0):
                continue
            # rate limit (requests in last 60 seconds)
            if _count_requests_in_window(c.get("id"), 60) >= rpm:
                continue
            # daily quota
            if dq != -1:
                tz_name = c.get("default_timezone") or "UTC"
                if _count_requests_today(c.get("id"), tz_name) >= dq:
                    continue
            return c, k, None
        # Determine whether it's quota or rate limiting across all candidates
        # If any candidate exists but all fail due to quota => QUOTA_EXCEEDED; else RATE_LIMIT
        any_candidate = False
        any_quota_ok = False
        any_rate_ok = False
        for k in active_keys:
            c = active_clients.get(k.get("client_id"))
            if not c:
                continue
            any_candidate = True
            rpm = c.get("rate_limit_rpm")
            dq = c.get("daily_quota_requests")
            if isinstance(rpm, int) and 1 <= rpm <= 6000:
                if _count_requests_in_window(c.get("id"), 60) < rpm:
                    any_rate_ok = True
            if isinstance(dq, int) and (dq == -1 or dq >= 0):
                if dq == -1:
                    any_quota_ok = True
                else:
                    tz_name = c.get("default_timezone") or "UTC"
                    if _count_requests_today(c.get("id"), tz_name) < dq:
                        any_quota_ok = True
        if not any_candidate:
            return None, None, ("UNAUTHORIZED", "No active API key/client available for this request")
        if not any_quota_ok:
            return None, None, ("QUOTA_EXCEEDED", "Daily request quota exceeded")
        if not any_rate_ok:
            return None, None, ("RATE_LIMIT", "Rate limit exceeded")
        return None, None, ("UNAUTHORIZED", "Unauthorized")

    client, key, auth_err = _pick_auth_context()
    if auth_err:
        code, msg = auth_err
        base_inv["client_id"] = chosen_client.get("id") if chosen_client else None
        base_inv["api_key_id"] = chosen_key.get("id") if chosen_key else None
        base_inv["status"] = "rate_limited" if code in ("RATE_LIMIT", "QUOTA_EXCEEDED") else "failed"
        base_inv["error_code"] = code
        base_inv["error_message"] = msg
        base_inv["latency_ms"] = int((time.time() - start) * 1000)
        base_inv["updated_at"] = _iso(_now_utc())
        invs.append(base_inv)
        _save("tool_invocations.json", invs)
        if code == "QUOTA_EXCEEDED":
            return _err("QUOTA_EXCEEDED", msg)
        if code == "RATE_LIMIT":
            return _err("RATE_LIMIT", msg)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Update chosen invocation with actual auth context
    base_inv["client_id"] = client.get("id")
    base_inv["api_key_id"] = key.get("id")

    # Find data source by code for weibo hotspots
    source = None
    for s in sources:
        if s.get("code") == "weibo_hotspots":
            source = s
            break
    if not source or source.get("status") == "disabled":
        # record failure
        base_inv["status"] = "failed"
        base_inv["error_code"] = "NOT_FOUND"
        base_inv["error_message"] = "Data source not available"
        base_inv["latency_ms"] = int((time.time() - start) * 1000)
        base_inv["updated_at"] = _iso(_now_utc())
        invs.append(base_inv)
        _save("tool_invocations.json", invs)
        return _err("NOT_FOUND", "No available snapshot")

    # Determine effective limit (default_limit if no limit)
    max_lim = source.get("max_limit")
    def_lim = source.get("default_limit")
    eff_limit = limit_val
    if eff_limit is None:
        eff_limit = def_lim if isinstance(def_lim, int) and def_lim >= 1 else None
    if eff_limit is not None:
        if isinstance(max_lim, int) and max_lim >= 1:
            if eff_limit > max_lim:
                eff_limit = max_lim
        if eff_limit <= 0:
            # Should not happen but protect
            base_inv["status"] = "failed"
            base_inv["error_code"] = "VALIDATION_ERROR"
            base_inv["error_message"] = "limit must be greater than 0"
            base_inv["latency_ms"] = int((time.time() - start) * 1000)
            base_inv["updated_at"] = _iso(_now_utc())
            invs.append(base_inv)
            _save("tool_invocations.json", invs)
            return _err("VALIDATION_ERROR", "limit must be greater than 0")

    cache_key = "weibo_hotspots|default"

    # Pick latest fresh unexpired snapshot for this source+cache_key
    source_id = source.get("id")
    fresh = []
    for sn in snaps:
        if sn.get("source_id") != source_id:
            continue
        if sn.get("cache_key") != cache_key:
            continue
        if sn.get("status") != "fresh":
            continue
        exp = _parse_dt(sn.get("expires_at"))
        if exp and exp > now:
            fresh.append(sn)
    fresh.sort(key=lambda x: (_parse_dt(x.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)

    used_snapshot = None
    items = None
    status = None
    warn = None

    if fresh:
        used_snapshot = fresh[0]
        status = "served_from_cache"
        items = used_snapshot.get("normalized_items")
    else:
        # No live fetch implemented offline: attempt stale-while-revalidate (optional)
        candidates = []
        for sn in snaps:
            if sn.get("source_id") != source_id:
                continue
            if sn.get("cache_key") != cache_key:
                continue
            if sn.get("status") in ("fresh", "stale"):
                candidates.append(sn)
        candidates.sort(key=lambda x: (_parse_dt(x.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
        if candidates:
            used_snapshot = candidates[0]
            # mark stale if it was fresh but expired (allowed transition fresh->stale)
            if used_snapshot.get("status") == "fresh":
                exp = _parse_dt(used_snapshot.get("expires_at"))
                if exp is not None and exp <= now:
                    used_snapshot["status"] = "stale"
                    used_snapshot["updated_at"] = _iso(_now_utc())
                    _save("fetch_snapshots.json", snaps)
            status = "served_from_cache"
            warn = "Serving stale snapshot (upstream refresh unavailable)"
            items = used_snapshot.get("normalized_items")
        else:
            base_inv["status"] = "failed"
            base_inv["error_code"] = "NOT_FOUND"
            base_inv["error_message"] = "Upstream fetch failed and no available snapshot"
            base_inv["latency_ms"] = int((time.time() - start) * 1000)
            base_inv["snapshot_ids"] = []
            base_inv["updated_at"] = _iso(_now_utc())
            invs.append(base_inv)
            # update last_used_at for key (best-effort)
            for kk in keys:
                if kk.get("id") == key.get("id"):
                    kk["last_used_at"] = _iso(_now_utc())
                    kk["updated_at"] = _iso(_now_utc())
                    break
            _save("api_keys.json", keys)
            _save("tool_invocations.json", invs)
            return _err("NOT_FOUND", "No available snapshot")

    # Normalize items list
    if items is None:
        items = []
    if not isinstance(items, list):
        # Snapshot corrupted: treat as failure (no success without effect)
        base_inv["status"] = "failed"
        base_inv["error_code"] = "NOT_FOUND"
        base_inv["error_message"] = "Snapshot has no usable items"
        base_inv["latency_ms"] = int((time.time() - start) * 1000)
        base_inv["snapshot_ids"] = [used_snapshot.get("id")] if used_snapshot else []
        base_inv["updated_at"] = _iso(_now_utc())
        invs.append(base_inv)
        for kk in keys:
            if kk.get("id") == key.get("id"):
                kk["last_used_at"] = _iso(_now_utc())
                kk["updated_at"] = _iso(_now_utc())
                break
        _save("api_keys.json", keys)
        _save("tool_invocations.json", invs)
        return _err("NOT_FOUND", "No available snapshot")

    out_items = items[:eff_limit] if isinstance(eff_limit, int) and eff_limit >= 1 else items

    # Finalize invocation
    base_inv["status"] = status
    base_inv["snapshot_ids"] = [used_snapshot.get("id")] if used_snapshot else []
    base_inv["latency_ms"] = int((time.time() - start) * 1000)
    base_inv["updated_at"] = _iso(_now_utc())
    if warn:
        base_inv["error_code"] = "STALE_SERVED"
        base_inv["error_message"] = warn

    invs.append(base_inv)

    # Update key last_used_at
    for kk in keys:
        if kk.get("id") == key.get("id"):
            kk["last_used_at"] = _iso(_now_utc())
            kk["updated_at"] = _iso(_now_utc())
            break

    _save("api_keys.json", keys)
    _save("tool_invocations.json", invs)

    resp = {
        "tool_name": "get-weibo-hotspots",
        "source": {"id": source_id, "code": source.get("code"), "display_name": source.get("display_name")},
        "snapshot": {
            "id": used_snapshot.get("id") if used_snapshot else None,
            "status": used_snapshot.get("status") if used_snapshot else None,
            "fetched_at": used_snapshot.get("fetched_at") if used_snapshot else None,
            "expires_at": used_snapshot.get("expires_at") if used_snapshot else None,
            "cache_key": cache_key,
        },
        "items": out_items,
        "meta": {
            "requested_limit": limit,
            "effective_limit": eff_limit,
            "returned": len(out_items) if isinstance(out_items, list) else 0,
            "total_in_snapshot": len(items) if isinstance(items, list) else 0,
            "warning": warn,
        },
    }
    return resp

def get_realtime_horoscope(type=None, time=None, **_extra):
    import json, os, datetime, uuid, time as _time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL_NAME = "get-realtime-horoscope"
    t0 = _time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"pulse_{prefix}_{uuid.uuid4().hex}"

    def _inv_base(client_id, api_key_id, request_params):
        now = _now_utc()
        return {
            "id": _gen_id("inv"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": TOOL_NAME,
            "request_params": request_params,
            "limit": None,
            "horoscope_type": request_params.get("type"),
            "horoscope_time": request_params.get("time"),
            "sentence_random": None,
            "status": "received",
            "snapshot_ids": None,
            "latency_ms": None,
            "error_code": None,
            "error_message": None,
            "invoked_at": _dt_iso(now),
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }

    # additionalProperties=false
    if _extra:
        return _err("VALIDATION_ERROR", "Unknown parameters", unknown=list(_extra.keys()))

    allowed_types = [
        "aries", "taurus", "gemini", "cancer", "leo", "virgo",
        "libra", "scorpio", "sagittarius", "capricorn", "aquarius", "pisces"
    ]
    allowed_times = ["today", "nextday", "week", "month"]
    if type not in set(allowed_types):
        return _err("VALIDATION_ERROR", "type must be one of allowed enum", allowed=allowed_types)
    if time not in set(allowed_times):
        return _err("VALIDATION_ERROR", "time must be one of allowed enum", allowed=allowed_times)

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    data_sources = _load("data_sources.json")
    fetch_snapshots = _load("fetch_snapshots.json")
    invocations = _load("tool_invocations.json")

    client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}
    # Ambient auth: find any usable active key + active client (must exist somewhere)
    client = None
    key = None
    for k in api_keys:
        if not isinstance(k, dict) or k.get("status") != "active":
            continue
        c = client_by_id.get(k.get("client_id"))
        if c and c.get("status") == "active":
            client, key = c, k
            break

    # Must record invocation even if unauthorized/rate limited
    req_params = {"type": type, "time": time}
    if not client or not key:
        inv = _inv_base(client_id="unknown", api_key_id="unknown", request_params=req_params)
        inv["status"] = "failed"
        inv["error_code"] = "UNAUTHORIZED"
        inv["error_message"] = "No active api_key+api_client available"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Quota/rate checks
    now = _now_utc()
    def _client_day_key(c_row):
        tz = c_row.get("default_timezone") or "UTC"
        # minimal TZ support for Asia/Shanghai and Asia/Hong_Kong; fallback UTC
        off_min = 0
        if tz in ("Asia/Shanghai", "Asia/Hong_Kong"):
            off_min = 8 * 60
        local = now + datetime.timedelta(minutes=off_min)
        return local.date().isoformat()

    def _count_today(client_id):
        day = _client_day_key(client)
        n = 0
        for r in invocations:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            dt = _dt_parse(r.get("invoked_at"))
            if not dt:
                continue
            # interpret invoked_at as UTC
            off_min = 8 * 60 if (client.get("default_timezone") in ("Asia/Shanghai", "Asia/Hong_Kong")) else 0
            local = dt + datetime.timedelta(minutes=off_min)
            if local.date().isoformat() == day:
                n += 1
        return n

    def _count_last_minute(client_id):
        window_start = now - datetime.timedelta(seconds=60)
        n = 0
        for r in invocations:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            dt = _dt_parse(r.get("invoked_at"))
            if dt and dt >= window_start:
                n += 1
        return n

    inv = _inv_base(client_id=client["id"], api_key_id=key["id"], request_params=req_params)

    rpm = client.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    if _count_last_minute(client["id"]) >= rpm:
        inv["status"] = "rate_limited"
        inv["error_code"] = "RPM_EXCEEDED"
        inv["error_message"] = f"Rate limit exceeded ({rpm} rpm); please retry later"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=30)

    dq = client.get("daily_quota_requests")
    if not isinstance(dq, int):
        dq = -1
    if dq != -1 and _count_today(client["id"]) >= dq:
        inv["status"] = "rate_limited"
        inv["error_code"] = "DAILY_QUOTA_EXCEEDED"
        inv["error_message"] = f"Daily quota exceeded ({dq} requests)"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # Find data source for horoscope (category=horoscope) - prefer enabled then degraded
    horoscope_sources = [s for s in data_sources if isinstance(s, dict) and s.get("category") == "horoscope"]
    preferred = None
    for st in ("enabled", "degraded", "disabled"):
        for s in horoscope_sources:
            if s.get("status") == st:
                preferred = s
                break
        if preferred:
            break
    if not preferred:
        inv["status"] = "failed"
        inv["error_code"] = "NOT_FOUND"
        inv["error_message"] = "No horoscope data source configured"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No available snapshot")

    cache_key = f"horoscope|type={type}|time={time}"
    # Find latest fresh, unexpired snapshot
    cand = []
    for sn in fetch_snapshots:
        if not isinstance(sn, dict):
            continue
        if sn.get("source_id") != preferred.get("id"):
            continue
        if sn.get("cache_key") != cache_key:
            continue
        fetched_at = _dt_parse(sn.get("fetched_at"))
        expires_at = _dt_parse(sn.get("expires_at"))
        if sn.get("status") == "fresh" and fetched_at and expires_at and expires_at > now:
            cand.append((fetched_at, sn))
    cand.sort(key=lambda x: x[0], reverse=True)
    snapshot = cand[0][1] if cand else None

    warning = None
    if not snapshot:
        # stale-while-revalidate: pick latest non-expired stale/fresh (even if expired?) - rule says allow older unexpired
        fallback = []
        for sn in fetch_snapshots:
            if not isinstance(sn, dict):
                continue
            if sn.get("source_id") != preferred.get("id") or sn.get("cache_key") != cache_key:
                continue
            fetched_at = _dt_parse(sn.get("fetched_at"))
            expires_at = _dt_parse(sn.get("expires_at"))
            if fetched_at and expires_at and expires_at > now and sn.get("status") in ("stale", "fresh"):
                fallback.append((fetched_at, sn))
        fallback.sort(key=lambda x: x[0], reverse=True)
        if fallback:
            snapshot = fallback[0][1]
            # if it was fresh but we're here, it likely failed checks; mark stale if allowed
            if snapshot.get("status") == "fresh":
                snapshot["status"] = "stale"
                snapshot["updated_at"] = _dt_iso(_now_utc())
                _save("fetch_snapshots.json", fetch_snapshots)
            warning = "Serving stale snapshot (stale-while-revalidate)"
        else:
            inv["status"] = "failed"
            inv["error_code"] = "NOT_FOUND"
            inv["error_message"] = "No available snapshot for requested type/time"
            inv["latency_ms"] = int((_time.time() - t0) * 1000)
            inv["updated_at"] = _dt_iso(_now_utc())
            invocations.append(inv)
            _save("tool_invocations.json", invocations)
            return _err("NOT_FOUND", "No available snapshot")

    items = snapshot.get("normalized_items")
    if not isinstance(items, list):
        items = []
    # Find matching row; if snapshot already keyed by type/time, allow first item
    chosen = None
    for it in items:
        if not isinstance(it, dict):
            continue
        if it.get("type") == type and it.get("time") == time:
            chosen = it
            break
    if not chosen and len(items) == 1 and isinstance(items[0], dict):
        # accept single item even if missing fields, but must not fabricate
        chosen = items[0]
    if not chosen:
        inv["status"] = "failed"
        inv["error_code"] = "NOT_FOUND"
        inv["error_message"] = "Requested horoscope not present in snapshot"
        inv["snapshot_ids"] = [snapshot.get("id")] if snapshot.get("id") else None
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Horoscope not found in current snapshot")

    inv["snapshot_ids"] = [snapshot.get("id")] if snapshot.get("id") else None
    inv["status"] = "served_from_cache"
    if warning:
        inv["error_code"] = "STALE_SNAPSHOT"
        inv["error_message"] = warning
    inv["latency_ms"] = int((_time.time() - t0) * 1000)
    inv["updated_at"] = _dt_iso(_now_utc())
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    # Update api_key last_used_at
    key["last_used_at"] = _dt_iso(_now_utc())
    key["updated_at"] = _dt_iso(_now_utc())
    _save("api_keys.json", api_keys)

    return {"data": chosen, "meta": {"snapshot_id": snapshot.get("id"), "cache_key": cache_key, "source_id": preferred.get("id")}}

def get_inspirational_english_sentence(random=None, **_extra):
    import json, os, datetime, uuid, time as _time, random as _random
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL_NAME = "get-inspirational-english-sentence"
    t0 = _time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"pulse_{prefix}_{uuid.uuid4().hex}"

    def _inv_base(client_id, api_key_id, request_params):
        now = _now_utc()
        return {
            "id": _gen_id("inv"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": TOOL_NAME,
            "request_params": request_params,
            "limit": None,
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": request_params.get("random"),
            "status": "received",
            "snapshot_ids": None,
            "latency_ms": None,
            "error_code": None,
            "error_message": None,
            "invoked_at": _dt_iso(now),
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }

    if _extra:
        return _err("VALIDATION_ERROR", "Unknown parameters", unknown=list(_extra.keys()))
    if not isinstance(random, bool):
        return _err("VALIDATION_ERROR", "random must be boolean")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    data_sources = _load("data_sources.json")
    fetch_snapshots = _load("fetch_snapshots.json")
    invocations = _load("tool_invocations.json")

    client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}
    client = None
    key = None
    for k in api_keys:
        if not isinstance(k, dict) or k.get("status") != "active":
            continue
        c = client_by_id.get(k.get("client_id"))
        if c and c.get("status") == "active":
            client, key = c, k
            break

    req_params = {"random": random}
    if not client or not key:
        inv = _inv_base(client_id="unknown", api_key_id="unknown", request_params=req_params)
        inv["status"] = "failed"
        inv["error_code"] = "UNAUTHORIZED"
        inv["error_message"] = "No active api_key+api_client available"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", "Unauthorized")

    now = _now_utc()
    def _client_day_key(c_row):
        tz = c_row.get("default_timezone") or "UTC"
        off_min = 0
        if tz in ("Asia/Shanghai", "Asia/Hong_Kong"):
            off_min = 8 * 60
        local = now + datetime.timedelta(minutes=off_min)
        return local.date().isoformat()

    def _count_today(client_id):
        day = _client_day_key(client)
        n = 0
        off_min = 8 * 60 if (client.get("default_timezone") in ("Asia/Shanghai", "Asia/Hong_Kong")) else 0
        for r in invocations:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            dt = _dt_parse(r.get("invoked_at"))
            if not dt:
                continue
            local = dt + datetime.timedelta(minutes=off_min)
            if local.date().isoformat() == day:
                n += 1
        return n

    def _count_last_minute(client_id):
        window_start = now - datetime.timedelta(seconds=60)
        n = 0
        for r in invocations:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            dt = _dt_parse(r.get("invoked_at"))
            if dt and dt >= window_start:
                n += 1
        return n

    inv = _inv_base(client_id=client["id"], api_key_id=key["id"], request_params=req_params)

    rpm = client.get("rate_limit_rpm")
    if not isinstance(rpm, int) or rpm < 1:
        rpm = 60
    if _count_last_minute(client["id"]) >= rpm:
        inv["status"] = "rate_limited"
        inv["error_code"] = "RPM_EXCEEDED"
        inv["error_message"] = f"Rate limit exceeded ({rpm} rpm); please retry later"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=30)

    dq = client.get("daily_quota_requests")
    if not isinstance(dq, int):
        dq = -1
    if dq != -1 and _count_today(client["id"]) >= dq:
        inv["status"] = "rate_limited"
        inv["error_code"] = "DAILY_QUOTA_EXCEEDED"
        inv["error_message"] = f"Daily quota exceeded ({dq} requests)"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # Find sentence data source (category=sentence) prefer enabled then degraded
    sentence_sources = [s for s in data_sources if isinstance(s, dict) and s.get("category") == "sentence"]
    ds = None
    for st in ("enabled", "degraded", "disabled"):
        for s in sentence_sources:
            if s.get("status") == st:
                ds = s
                break
        if ds:
            break
    if not ds:
        inv["status"] = "failed"
        inv["error_code"] = "NOT_FOUND"
        inv["error_message"] = "No sentence data source configured"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No available sentence snapshot")

    cache_key = f"sentence|random={'true' if random else 'false'}"

    # If random=true, prefer any fresh unexpired snapshot; otherwise pick latest fresh unexpired
    cand = []
    for sn in fetch_snapshots:
        if not isinstance(sn, dict):
            continue
        if sn.get("source_id") != ds.get("id") or sn.get("cache_key") != cache_key:
            continue
        fetched_at = _dt_parse(sn.get("fetched_at"))
        expires_at = _dt_parse(sn.get("expires_at"))
        if sn.get("status") == "fresh" and fetched_at and expires_at and expires_at > now:
            cand.append((fetched_at, sn))
    cand.sort(key=lambda x: x[0], reverse=True)
    snapshot = cand[0][1] if cand else None

    warning = None
    if not snapshot:
        # stale-while-revalidate fallback
        fallback = []
        for sn in fetch_snapshots:
            if not isinstance(sn, dict):
                continue
            if sn.get("source_id") != ds.get("id") or sn.get("cache_key") != cache_key:
                continue
            fetched_at = _dt_parse(sn.get("fetched_at"))
            expires_at = _dt_parse(sn.get("expires_at"))
            if fetched_at and expires_at and expires_at > now and sn.get("status") in ("stale", "fresh"):
                fallback.append((fetched_at, sn))
        fallback.sort(key=lambda x: x[0], reverse=True)
        if fallback:
            snapshot = fallback[0][1]
            if snapshot.get("status") == "fresh":
                snapshot["status"] = "stale"
                snapshot["updated_at"] = _dt_iso(_now_utc())
                _save("fetch_snapshots.json", fetch_snapshots)
            warning = "Serving stale snapshot (stale-while-revalidate)"
        else:
            inv["status"] = "failed"
            inv["error_code"] = "NOT_FOUND"
            inv["error_message"] = "No available sentence snapshot"
            inv["latency_ms"] = int((_time.time() - t0) * 1000)
            inv["updated_at"] = _dt_iso(_now_utc())
            invocations.append(inv)
            _save("tool_invocations.json", invocations)
            return _err("NOT_FOUND", "No available sentence snapshot")

    items = snapshot.get("normalized_items")
    if not isinstance(items, list):
        items = []
    chosen = None
    if random:
        dict_items = [it for it in items if isinstance(it, dict)]
        if dict_items:
            chosen = _random.choice(dict_items)
    else:
        for it in items:
            if isinstance(it, dict):
                chosen = it
                break

    if not chosen:
        inv["status"] = "failed"
        inv["error_code"] = "NOT_FOUND"
        inv["error_message"] = "No sentence item in snapshot"
        inv["snapshot_ids"] = [snapshot.get("id")] if snapshot.get("id") else None
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No available sentence snapshot")

    inv["snapshot_ids"] = [snapshot.get("id")] if snapshot.get("id") else None
    inv["status"] = "served_from_cache"
    if warning:
        inv["error_code"] = "STALE_SNAPSHOT"
        inv["error_message"] = warning
    inv["latency_ms"] = int((_time.time() - t0) * 1000)
    inv["updated_at"] = _dt_iso(_now_utc())
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    key["last_used_at"] = _dt_iso(_now_utc())
    key["updated_at"] = _dt_iso(_now_utc())
    _save("api_keys.json", api_keys)

    return {"data": chosen, "meta": {"snapshot_id": snapshot.get("id"), "cache_key": cache_key, "source_id": ds.get("id")}}

def internet_hotspots_aggregator(limit=None, **_extra):
    import json, os, datetime, time, random

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"{prefix}_{int(time.time()*1000)}_{random.randint(100000, 999999)}"

    def _pick_auth_context(api_clients, api_keys):
        for k in api_keys:
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            c = next((x for x in api_clients if x.get("id") == cid and x.get("status") == "active"), None)
            if not c:
                continue
            return c, k
        return None, None

    def _check_limits(client, invocations, now_dt):
        rpm = client.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 60
        window_start = now_dt - datetime.timedelta(seconds=60)
        recent = 0
        for r in invocations:
            if r.get("client_id") != client.get("id"):
                continue
            t = _dt_parse(r.get("invoked_at"))
            if t and t > window_start and t <= now_dt:
                recent += 1
        if recent >= rpm:
            return "RATE_LIMIT", f"Rate limit exceeded: {recent}/{rpm} requests per minute"

        quota = client.get("daily_quota_requests")
        if isinstance(quota, int) and quota != -1:
            tzname = client.get("default_timezone") or "UTC"
            try:
                if tzname.upper() == "UTC":
                    tz = datetime.timezone.utc
                else:
                    tz = datetime.datetime.now().astimezone().tzinfo
            except Exception:
                tz = datetime.timezone.utc
            local_now = now_dt.astimezone(tz)
            day_start_local = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
            day_start = day_start_local.astimezone(datetime.timezone.utc)
            used = 0
            for r in invocations:
                if r.get("client_id") != client.get("id"):
                    continue
                t = _dt_parse(r.get("invoked_at"))
                if t and t >= day_start and t <= now_dt:
                    used += 1
            if used >= quota:
                return "QUOTA_EXCEEDED", f"Daily quota exceeded: {used}/{quota} requests"
        return None, None

    start = time.time()
    tool_name = "internet-hotspots-aggregator"
    now_dt = _now()

    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be a number > 0")
        if not (limit > 0):
            return _err("VALIDATION_ERROR", "limit must be > 0")
        limit_val = int(limit)
        if limit_val <= 0:
            return _err("VALIDATION_ERROR", "limit must be > 0")
    else:
        limit_val = None

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    invocations = _load("tool_invocations.json")
    data_sources = _load("data_sources.json")
    snapshots = _load("fetch_snapshots.json")

    client, api_key = _pick_auth_context(api_clients, api_keys)

    inv_id = _gen_id("invk")
    req_params = {}
    if limit is not None:
        req_params["limit"] = limit
    invocation = {
        "id": inv_id,
        "client_id": client.get("id") if client else "unknown",
        "api_key_id": api_key.get("id") if api_key else "unknown",
        "tool_name": tool_name,
        "request_params": req_params,
        "limit": float(limit) if limit is not None else None,
        "horoscope_type": None,
        "horoscope_time": None,
        "sentence_random": None,
        "status": "received",
        "snapshot_ids": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "invoked_at": _dt_iso(now_dt),
        "created_at": _dt_iso(now_dt),
        "updated_at": _dt_iso(now_dt),
    }

    if not client or not api_key:
        invocation["status"] = "failed"
        invocation["error_code"] = "UNAUTHORIZED"
        invocation["error_message"] = "No active API key/client available"
        invocation["latency_ms"] = int((time.time() - start) * 1000)
        invocation["updated_at"] = _dt_iso(_now())
        invocations.append(invocation)
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", "Unauthorized")

    limit_code, limit_msg = _check_limits(client, invocations, now_dt)
    if limit_code:
        invocation["status"] = "rate_limited"
        invocation["error_code"] = limit_code
        invocation["error_message"] = limit_msg
        invocation["latency_ms"] = int((time.time() - start) * 1000)
        invocation["updated_at"] = _dt_iso(_now())
        invocations.append(invocation)
        _save("tool_invocations.json", invocations)
        return _err(limit_code, limit_msg)

    # Hotspot sources = category hotspots, enabled or degraded; exclude aggregator source itself
    hotspot_sources = [
        s for s in data_sources
        if s.get("category") == "hotspots"
        and s.get("status") in ("enabled", "degraded")
        and s.get("code") not in ("internet_hotspots_aggregator",)
    ]

    grouped = {}
    used_snapshot_ids = []
    degraded_sources = []
    for src in hotspot_sources:
        code = src.get("code")
        # Default cache_key: <code>|default for no-arg hot榜 tools
        cache_key = f"{code}|default"

        # Find latest fresh snapshot unexpired
        fresh = []
        for sn in snapshots:
            if sn.get("source_id") != src.get("id"):
                continue
            if sn.get("cache_key") != cache_key:
                continue
            if sn.get("status") != "fresh":
                continue
            exp = _dt_parse(sn.get("expires_at"))
            if exp and exp > now_dt:
                fetched = _dt_parse(sn.get("fetched_at")) or _dt_parse(sn.get("created_at")) or now_dt
                fresh.append((fetched, sn))
        fresh.sort(key=lambda x: x[0], reverse=True)
        chosen = fresh[0][1] if fresh else None
        if not chosen:
            degraded_sources.append({"code": code, "reason": "no_fresh_snapshot"})
            continue

        max_limit = src.get("max_limit")
        clamp = max_limit if isinstance(max_limit, int) and max_limit >= 1 else None

        eff_limit = limit_val
        if eff_limit is None:
            dl = src.get("default_limit")
            if isinstance(dl, int) and dl >= 1:
                eff_limit = dl
        if eff_limit is None:
            eff_limit = 10
        if clamp is not None and eff_limit > clamp:
            eff_limit = clamp

        items = chosen.get("normalized_items") or []
        if not isinstance(items, list):
            items = []
        out_items = items[:eff_limit]

        if out_items:
            grouped[code] = {
                "source": {"code": code, "display_name": src.get("display_name")},
                "snapshot": {
                    "id": chosen.get("id"),
                    "fetched_at": chosen.get("fetched_at"),
                    "expires_at": chosen.get("expires_at"),
                    "status": chosen.get("status"),
                },
                "items": out_items,
                "meta": {"limit": eff_limit, "returned": len(out_items)},
            }
            used_snapshot_ids.append(chosen.get("id"))
        else:
            degraded_sources.append({"code": code, "reason": "empty_items"})

    if not grouped:
        invocation["status"] = "failed"
        invocation["error_code"] = "NOT_FOUND"
        invocation["error_message"] = "No available snapshots across platforms"
        invocation["latency_ms"] = int((time.time() - start) * 1000)
        invocation["updated_at"] = _dt_iso(_now())
        invocations.append(invocation)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No available aggregated hotspots")

    # Optional: mark sources with missing data as degraded (business rule says optional)
    if degraded_sources:
        changed = False
        for ds in degraded_sources:
            src = next((s for s in data_sources if s.get("code") == ds.get("code")), None)
            if src and src.get("status") == "enabled":
                src["status"] = "degraded"
                src["updated_at"] = _dt_iso(now_dt)
                changed = True
        if changed:
            _save("data_sources.json", data_sources)

        invocation["request_params"] = dict(invocation["request_params"])
        invocation["request_params"]["degraded_sources"] = degraded_sources

    api_key["last_used_at"] = _dt_iso(now_dt)
    api_key["updated_at"] = _dt_iso(now_dt)
    for i, k in enumerate(api_keys):
        if k.get("id") == api_key.get("id"):
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    invocation["status"] = "served_from_cache"
    invocation["snapshot_ids"] = used_snapshot_ids
    invocation["latency_ms"] = int((time.time() - start) * 1000)
    invocation["updated_at"] = _dt_iso(_now())
    invocations.append(invocation)
    _save("tool_invocations.json", invocations)

    return {
        "tool_name": tool_name,
        "meta": {
            "platforms": len(grouped),
            "missing_platforms": len(degraded_sources),
            "per_platform_limit_requested": (int(limit_val) if limit_val is not None else None),
        },
        "groups": grouped,
        "warnings": (degraded_sources if degraded_sources else []),
    }

def today_headlines_hotspots(limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return _now_utc().isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    start = time.time()
    now = _now_utc()

    # Validate inputs
    req_params = {}
    limit_val = None
    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be a number greater than 0")
        if not (limit > 0):
            return _err("VALIDATION_ERROR", "limit must be greater than 0")
        req_params["limit"] = limit
        limit_val = int(limit) if float(limit).is_integer() else int(limit)
        if limit_val <= 0:
            return _err("VALIDATION_ERROR", "limit must be greater than 0")

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    sources = _load("data_sources.json")
    snaps = _load("fetch_snapshots.json")
    invs = _load("tool_invocations.json")

    active_clients = {c.get("id"): c for c in clients if c.get("status") == "active"}
    active_keys = [k for k in keys if k.get("status") == "active" and k.get("client_id") in active_clients]

    inv_id = _gen_id("invk")
    base_inv = {
        "id": inv_id,
        "client_id": None,
        "api_key_id": None,
        "tool_name": "today-headlines-hotspots",
        "request_params": req_params,
        "limit": float(limit) if limit is not None else None,
        "horoscope_type": None,
        "horoscope_time": None,
        "sentence_random": None,
        "status": "received",
        "snapshot_ids": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "invoked_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }

    if not active_keys:
        base_inv["status"] = "failed"
        base_inv["error_code"] = "UNAUTHORIZED"
        base_inv["error_message"] = "No active API key/client available for this request"
        base_inv["latency_ms"] = int((time.time() - start) * 1000)
        base_inv["updated_at"] = _iso(_now_utc())
        invs.append(base_inv)
        _save("tool_invocations.json", invs)
        return _err("UNAUTHORIZED", "Unauthorized")

    def _count_requests_in_window(client_id, window_seconds):
        cutoff = now - datetime.timedelta(seconds=window_seconds)
        cnt = 0
        for r in invs:
            if r.get("client_id") != client_id:
                continue
            t = _parse_dt(r.get("invoked_at"))
            if t is None:
                continue
            if t >= cutoff:
                cnt += 1
        return cnt

    def _count_requests_today(client_id, tz_name):
        try:
            tz = datetime.timezone.utc
            if isinstance(tz_name, str) and tz_name:
                try:
                    tz = datetime.ZoneInfo(tz_name)
                except Exception:
                    tz = datetime.timezone.utc
        except Exception:
            tz = datetime.timezone.utc
        local_now = now.astimezone(tz)
        day_start_local = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
        day_start = day_start_local.astimezone(datetime.timezone.utc)
        cnt = 0
        for r in invs:
            if r.get("client_id") != client_id:
                continue
            t = _parse_dt(r.get("invoked_at"))
            if t is None:
                continue
            if t >= day_start and t <= now:
                cnt += 1
        return cnt

    def _pick_auth_context():
        for k in active_keys:
            c = active_clients.get(k.get("client_id"))
            if not c:
                continue
            rpm = c.get("rate_limit_rpm")
            dq = c.get("daily_quota_requests")
            if not isinstance(rpm, int) or rpm < 1 or rpm > 6000:
                continue
            if not isinstance(dq, int) or not (dq == -1 or dq >= 0):
                continue
            if _count_requests_in_window(c.get("id"), 60) >= rpm:
                continue
            if dq != -1:
                tz_name = c.get("default_timezone") or "UTC"
                if _count_requests_today(c.get("id"), tz_name) >= dq:
                    continue
            return c, k, None
        any_candidate = False
        any_quota_ok = False
        any_rate_ok = False
        for k in active_keys:
            c = active_clients.get(k.get("client_id"))
            if not c:
                continue
            any_candidate = True
            rpm = c.get("rate_limit_rpm")
            dq = c.get("daily_quota_requests")
            if isinstance(rpm, int) and 1 <= rpm <= 6000:
                if _count_requests_in_window(c.get("id"), 60) < rpm:
                    any_rate_ok = True
            if isinstance(dq, int) and (dq == -1 or dq >= 0):
                if dq == -1:
                    any_quota_ok = True
                else:
                    tz_name = c.get("default_timezone") or "UTC"
                    if _count_requests_today(c.get("id"), tz_name) < dq:
                        any_quota_ok = True
        if not any_candidate:
            return None, None, ("UNAUTHORIZED", "No active API key/client available for this request")
        if not any_quota_ok:
            return None, None, ("QUOTA_EXCEEDED", "Daily request quota exceeded")
        if not any_rate_ok:
            return None, None, ("RATE_LIMIT", "Rate limit exceeded")
        return None, None, ("UNAUTHORIZED", "Unauthorized")

    client, key, auth_err = _pick_auth_context()
    if auth_err:
        code, msg = auth_err
        # attach some active key/client for FK consistency if possible
        k0 = active_keys[0]
        c0 = active_clients.get(k0.get("client_id"))
        base_inv["client_id"] = c0.get("id") if c0 else None
        base_inv["api_key_id"] = k0.get("id")
        base_inv["status"] = "rate_limited" if code in ("RATE_LIMIT", "QUOTA_EXCEEDED") else "failed"
        base_inv["error_code"] = code
        base_inv["error_message"] = msg
        base_inv["latency_ms"] = int((time.time() - start) * 1000)
        base_inv["updated_at"] = _iso(_now_utc())
        invs.append(base_inv)
        _save("tool_invocations.json", invs)
        if code == "QUOTA_EXCEEDED":
            return _err("QUOTA_EXCEEDED", msg)
        if code == "RATE_LIMIT":
            return _err("RATE_LIMIT", msg)
        return _err("UNAUTHORIZED", "Unauthorized")

    base_inv["client_id"] = client.get("id")
    base_inv["api_key_id"] = key.get("id")

    # Source code mapping
    source = None
    for s in sources:
        if s.get("code") == "today_headlines_hotspots":
            source = s
            break
    if not source or source.get("status") == "disabled":
        base_inv["status"] = "failed"
        base_inv["error_code"] = "NOT_FOUND"
        base_inv["error_message"] = "Data source not available"
        base_inv["latency_ms"] = int((time.time() - start) * 1000)
        base_inv["updated_at"] = _iso(_now_utc())
        invs.append(base_inv)
        for kk in keys:
            if kk.get("id") == key.get("id"):
                kk["last_used_at"] = _iso(_now_utc())
                kk["updated_at"] = _iso(_now_utc())
                break
        _save("api_keys.json", keys)
        _save("tool_invocations.json", invs)
        return _err("NOT_FOUND", "No available snapshot")

    # effective limit: default if not provided; clamp to max_limit
    max_lim = source.get("max_limit")
    def_lim = source.get("default_limit")
    eff_limit = limit_val
    if eff_limit is None:
        eff_limit = def_lim if isinstance(def_lim, int) and def_lim >= 1 else None
    if eff_limit is not None and isinstance(max_lim, int) and max_lim >= 1 and eff_limit > max_lim:
        eff_limit = max_lim

    cache_key = "today_headlines_hotspots|default"
    source_id = source.get("id")

    fresh = []
    for sn in snaps:
        if sn.get("source_id") != source_id:
            continue
        if sn.get("cache_key") != cache_key:
            continue
        if sn.get("status") != "fresh":
            continue
        exp = _parse_dt(sn.get("expires_at"))
        if exp and exp > now:
            fresh.append(sn)
    fresh.sort(key=lambda x: (_parse_dt(x.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)

    used_snapshot = None
    items = None
    status = None
    warn = None

    if fresh:
        used_snapshot = fresh[0]
        status = "served_from_cache"
        items = used_snapshot.get("normalized_items")
    else:
        candidates = []
        for sn in snaps:
            if sn.get("source_id") != source_id:
                continue
            if sn.get("cache_key") != cache_key:
                continue
            if sn.get("status") in ("fresh", "stale"):
                candidates.append(sn)
        candidates.sort(key=lambda x: (_parse_dt(x.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
        if candidates:
            used_snapshot = candidates[0]
            if used_snapshot.get("status") == "fresh":
                exp = _parse_dt(used_snapshot.get("expires_at"))
                if exp is not None and exp <= now:
                    used_snapshot["status"] = "stale"
                    used_snapshot["updated_at"] = _iso(_now_utc())
                    _save("fetch_snapshots.json", snaps)
            status = "served_from_cache"
            warn = "Serving stale snapshot (upstream refresh unavailable)"
            items = used_snapshot.get("normalized_items")
        else:
            base_inv["status"] = "failed"
            base_inv["error_code"] = "NOT_FOUND"
            base_inv["error_message"] = "Upstream fetch failed and no available snapshot"
            base_inv["snapshot_ids"] = []
            base_inv["latency_ms"] = int((time.time() - start) * 1000)
            base_inv["updated_at"] = _iso(_now_utc())
            invs.append(base_inv)
            for kk in keys:
                if kk.get("id") == key.get("id"):
                    kk["last_used_at"] = _iso(_now_utc())
                    kk["updated_at"] = _iso(_now_utc())
                    break
            _save("api_keys.json", keys)
            _save("tool_invocations.json", invs)
            return _err("NOT_FOUND", "No available snapshot")

    if items is None:
        items = []
    if not isinstance(items, list):
        base_inv["status"] = "failed"
        base_inv["error_code"] = "NOT_FOUND"
        base_inv["error_message"] = "Snapshot has no usable items"
        base_inv["snapshot_ids"] = [used_snapshot.get("id")] if used_snapshot else []
        base_inv["latency_ms"] = int((time.time() - start) * 1000)
        base_inv["updated_at"] = _iso(_now_utc())
        invs.append(base_inv)
        for kk in keys:
            if kk.get("id") == key.get("id"):
                kk["last_used_at"] = _iso(_now_utc())
                kk["updated_at"] = _iso(_now_utc())
                break
        _save("api_keys.json", keys)
        _save("tool_invocations.json", invs)
        return _err("NOT_FOUND", "No available snapshot")

    out_items = items[:eff_limit] if isinstance(eff_limit, int) and eff_limit >= 1 else items

    base_inv["status"] = status
    base_inv["snapshot_ids"] = [used_snapshot.get("id")] if used_snapshot else []
    base_inv["latency_ms"] = int((time.time() - start) * 1000)
    base_inv["updated_at"] = _iso(_now_utc())
    if warn:
        base_inv["error_code"] = "STALE_SERVED"
        base_inv["error_message"] = warn

    invs.append(base_inv)

    for kk in keys:
        if kk.get("id") == key.get("id"):
            kk["last_used_at"] = _iso(_now_utc())
            kk["updated_at"] = _iso(_now_utc())
            break

    _save("api_keys.json", keys)
    _save("tool_invocations.json", invs)

    return {
        "tool_name": "today-headlines-hotspots",
        "source": {"id": source_id, "code": source.get("code"), "display_name": source.get("display_name")},
        "snapshot": {
            "id": used_snapshot.get("id") if used_snapshot else None,
            "status": used_snapshot.get("status") if used_snapshot else None,
            "fetched_at": used_snapshot.get("fetched_at") if used_snapshot else None,
            "expires_at": used_snapshot.get("expires_at") if used_snapshot else None,
            "cache_key": cache_key,
        },
        "items": out_items,
        "meta": {
            "requested_limit": limit,
            "effective_limit": eff_limit,
            "returned": len(out_items) if isinstance(out_items, list) else 0,
            "total_in_snapshot": len(items) if isinstance(items, list) else 0,
            "warning": warn,
        },
    }

def the_paper_news_hotspots(limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.perf_counter()
    invoked_at = _now()

    # Validate params (JSON-schema: additionalProperties=false)
    if _extra:
        # unknown fields
        return _err("VALIDATION_ERROR", "Unknown parameter(s).", unknown_fields=sorted(list(_extra.keys())))
    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be a number.")
        if not (limit > 0):
            return _err("VALIDATION_ERROR", "limit must be greater than 0.")
        # service accepts number but uses integer count
        req_limit = int(limit)
        if req_limit <= 0:
            return _err("VALIDATION_ERROR", "limit must be greater than 0.")
    else:
        req_limit = None

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    data_sources = _load("data_sources.json")
    fetch_snapshots = _load("fetch_snapshots.json")
    tool_invocations = _load("tool_invocations.json")

    tool_name = "the-paper-news-hotspots"
    request_params = {}
    if limit is not None:
        request_params["limit"] = limit

    # Resolve a usable (client, key) pair from store (ambient auth)
    client_row = None
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        cid = k.get("client_id")
        if not cid:
            continue
        c = next((cc for cc in api_clients if isinstance(cc, dict) and cc.get("id") == cid), None)
        if not c or c.get("status") != "active":
            continue
        client_row = c
        key_row = k
        break

    # Helper to append invocation record (must always log)
    def _log_invocation(status, snapshot_ids=None, error_code=None, error_message=None, latency_ms=None):
        inv_id = _gen_id("invk")
        rec = {
            "id": inv_id,
            "client_id": client_row.get("id") if client_row else "unknown",
            "api_key_id": key_row.get("id") if key_row else "unknown",
            "tool_name": tool_name,
            "request_params": request_params,
            "limit": float(limit) if limit is not None else None,
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": status,
            "snapshot_ids": snapshot_ids,
            "latency_ms": latency_ms,
            "error_code": error_code,
            "error_message": error_message,
            "invoked_at": _iso(invoked_at),
            "created_at": _iso(invoked_at),
            "updated_at": _iso(invoked_at),
        }
        tool_invocations.append(rec)
        _save("tool_invocations.json", tool_invocations)
        return rec

    # If no usable auth context
    if not client_row or not key_row:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log_invocation(
            status="failed",
            snapshot_ids=None,
            error_code="UNAUTHORIZED",
            error_message="No active api_key/api_client combination available for this call.",
            latency_ms=latency_ms,
        )
        return _err("UNAUTHORIZED", "Unauthorized.")

    # Enforce rate limit and daily quota (based on tool_invocations history)
    client_id = client_row["id"]
    rate_limit_rpm = client_row.get("rate_limit_rpm")
    daily_quota_requests = client_row.get("daily_quota_requests")

    if not isinstance(rate_limit_rpm, int) or rate_limit_rpm < 1 or rate_limit_rpm > 6000:
        # Server misconfig; treat as validation-ish server side error
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log_invocation(
            status="failed",
            snapshot_ids=None,
            error_code="VALIDATION_ERROR",
            error_message="Client rate_limit_rpm misconfigured.",
            latency_ms=latency_ms,
        )
        return _err("VALIDATION_ERROR", "Client configuration invalid (rate_limit_rpm).")

    now_dt = invoked_at
    one_min_ago = now_dt - datetime.timedelta(minutes=1)

    def _invoked_at_dt(r):
        return _parse_dt(r.get("invoked_at")) or _parse_dt(r.get("created_at"))

    recent = 0
    for r in tool_invocations:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        dt = _invoked_at_dt(r)
        if dt and dt > one_min_ago:
            recent += 1

    if recent >= rate_limit_rpm:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log_invocation(
            status="rate_limited",
            snapshot_ids=None,
            error_code="RATE_LIMIT",
            error_message="Rate limit exceeded.",
            latency_ms=latency_ms,
        )
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit="rpm", rate_limit_rpm=rate_limit_rpm)

    if isinstance(daily_quota_requests, int) and daily_quota_requests != -1:
        # Natural day in client's timezone
        tzname = client_row.get("default_timezone") or "UTC"
        try:
            tz = datetime.timezone.utc if tzname.upper() == "UTC" else datetime.timezone(datetime.timedelta(hours=int(tzname)))
        except Exception:
            tz = datetime.timezone.utc
        local_now = now_dt.astimezone(tz)
        local_day_start = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
        day_start_utc = local_day_start.astimezone(datetime.timezone.utc)

        day_count = 0
        for r in tool_invocations:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            dt = _invoked_at_dt(r)
            if dt and dt >= day_start_utc:
                day_count += 1

        if day_count >= daily_quota_requests:
            latency_ms = int((time.perf_counter() - t0) * 1000)
            _log_invocation(
                status="rate_limited",
                snapshot_ids=None,
                error_code="QUOTA_EXCEEDED",
                error_message="Daily quota exceeded.",
                latency_ms=latency_ms,
            )
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", daily_quota_requests=daily_quota_requests)

    # Find data source
    source = next((s for s in data_sources if isinstance(s, dict) and s.get("code") == "the_paper_news_hotspots"), None)
    if not source:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log_invocation(
            status="failed",
            snapshot_ids=None,
            error_code="NOT_FOUND",
            error_message="Data source not configured.",
            latency_ms=latency_ms,
        )
        return _err("NOT_FOUND", "Data source not found.")
    if source.get("status") == "disabled":
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log_invocation(
            status="failed",
            snapshot_ids=None,
            error_code="NOT_FOUND",
            error_message="Data source is disabled.",
            latency_ms=latency_ms,
        )
        return _err("NOT_FOUND", "No snapshot available.")

    source_id = source.get("id")
    cache_key = "the_paper_news_hotspots|default"

    # Determine server-side limit (clamp)
    max_limit = source.get("max_limit")
    default_limit = source.get("default_limit")
    use_limit = req_limit
    if use_limit is None:
        use_limit = int(default_limit) if isinstance(default_limit, int) and default_limit >= 1 else None
    if use_limit is None:
        use_limit = 10
    if isinstance(max_limit, int) and max_limit >= 1:
        if use_limit > max_limit:
            use_limit = max_limit

    # Choose freshest unexpired snapshot for source_id+cache_key
    now_dt = _now()
    candidates = []
    for snap in fetch_snapshots:
        if not isinstance(snap, dict):
            continue
        if snap.get("source_id") != source_id:
            continue
        if snap.get("cache_key") != cache_key:
            continue
        if snap.get("status") != "fresh":
            continue
        exp = _parse_dt(snap.get("expires_at"))
        if exp and exp > now_dt:
            candidates.append(snap)

    def _fetched_at(s):
        return _parse_dt(s.get("fetched_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    snapshot = max(candidates, key=_fetched_at) if candidates else None

    # Record last_used_at on key
    key_row["last_used_at"] = _iso(invoked_at)
    key_row["updated_at"] = _iso(invoked_at)
    _save("api_keys.json", api_keys)

    if snapshot:
        items = snapshot.get("normalized_items") or []
        if not isinstance(items, list):
            items = []
        items_out = items[:use_limit]
        latency_ms = int((time.perf_counter() - t0) * 1000)
        inv = _log_invocation(
            status="served_from_cache",
            snapshot_ids=[snapshot.get("id")],
            error_code=None,
            error_message=None,
            latency_ms=latency_ms,
        )
        return {
            "tool_name": tool_name,
            "status": inv["status"],
            "from_cache": True,
            "source": {"id": source_id, "code": source.get("code"), "display_name": source.get("display_name")},
            "cache_key": cache_key,
            "snapshot_id": snapshot.get("id"),
            "fetched_at": snapshot.get("fetched_at"),
            "expires_at": snapshot.get("expires_at"),
            "limit": use_limit,
            "total_items": len(items),
            "items": items_out,
        }

    # No fresh snapshot: try stale-while-revalidate (optional) using latest non-failed snapshot that is not fresh or expired
    older = []
    for snap in fetch_snapshots:
        if not isinstance(snap, dict):
            continue
        if snap.get("source_id") != source_id or snap.get("cache_key") != cache_key:
            continue
        if snap.get("status") not in ("fresh", "stale"):
            continue
        older.append(snap)
    fallback = max(older, key=_fetched_at) if older else None
    if fallback:
        # Mark it stale (fresh -> stale transition only)
        if fallback.get("status") == "fresh":
            fallback["status"] = "stale"
            fallback["updated_at"] = _iso(now_dt)
            _save("fetch_snapshots.json", fetch_snapshots)

        items = fallback.get("normalized_items") or []
        if not isinstance(items, list):
            items = []
        items_out = items[:use_limit]
        latency_ms = int((time.perf_counter() - t0) * 1000)
        inv = _log_invocation(
            status="served_from_cache",
            snapshot_ids=[fallback.get("id")],
            error_code=None,
            error_message="Serving stale snapshot (stale-while-revalidate).",
            latency_ms=latency_ms,
        )
        return {
            "tool_name": tool_name,
            "status": inv["status"],
            "from_cache": True,
            "stale": True,
            "warning": "Serving stale snapshot (stale-while-revalidate).",
            "source": {"id": source_id, "code": source.get("code"), "display_name": source.get("display_name")},
            "cache_key": cache_key,
            "snapshot_id": fallback.get("id"),
            "fetched_at": fallback.get("fetched_at"),
            "expires_at": fallback.get("expires_at"),
            "limit": use_limit,
            "total_items": len(items),
            "items": items_out,
        }

    # No usable snapshot: treat as upstream failure/no data
    latency_ms = int((time.perf_counter() - t0) * 1000)
    _log_invocation(
        status="failed",
        snapshot_ids=None,
        error_code="NOT_FOUND",
        error_message="No available snapshot (upstream fetch failed or never succeeded).",
        latency_ms=latency_ms,
    )
    return _err("NOT_FOUND", "No snapshot available.")

def hupu_pedestrian_street_hotspots(limit=None, **_extra):
    import json, os, datetime, uuid, time as _time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"pulse_{prefix}_{uuid.uuid4().hex}"

    TOOL_NAME = "hupu-pedestrian-street-hotspots"
    t0 = _time.time()
    now = _now()

    if _extra:
        return _err("VALIDATION_ERROR", "Unknown parameters", unknown=list(_extra.keys()))
    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool) or limit <= 0:
            return _err("VALIDATION_ERROR", "limit must be a positive number")
        limit = int(limit)

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    data_sources = _load("data_sources.json")
    fetch_snapshots = _load("fetch_snapshots.json")
    invocations = _load("tool_invocations.json")

    client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}

    def _pick_ambient_auth():
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            c = client_by_id.get(k.get("client_id"))
            if c and c.get("status") == "active":
                return c, k
        return None, None

    def _client_day_key(dt_utc, tz_name):
        if not isinstance(tz_name, str) or not tz_name:
            tz_name = "UTC"
        offset = datetime.timedelta(0)
        if tz_name in ("Asia/Shanghai", "Asia/Hong_Kong"):
            offset = datetime.timedelta(hours=8)
        dt_local = dt_utc + offset
        return dt_local.date().isoformat()

    def _count_rpm(inv_rows, client_id, now_dt):
        window_start = now_dt - datetime.timedelta(seconds=60)
        cnt = 0
        for r in inv_rows:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            t = _dt_parse(r.get("invoked_at"))
            if t and t >= window_start and t <= now_dt:
                cnt += 1
        return cnt

    def _count_daily(inv_rows, client_id, day_key, tz_name):
        cnt = 0
        for r in inv_rows:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            t = _dt_parse(r.get("invoked_at"))
            if not t:
                continue
            if _client_day_key(t, tz_name) == day_key:
                cnt += 1
        return cnt

    def _inv_base(client_id, api_key_id, req_params):
        ts = _dt_iso(now)
        return {
            "id": _gen_id("inv"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": TOOL_NAME,
            "request_params": req_params,
            "limit": req_params.get("limit"),
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "received",
            "snapshot_ids": None,
            "latency_ms": None,
            "error_code": None,
            "error_message": None,
            "invoked_at": ts,
            "created_at": ts,
            "updated_at": ts,
        }

    client, key = _pick_ambient_auth()
    if not client or not key:
        inv = _inv_base("unknown", "unknown", {"limit": limit} if limit is not None else {})
        inv["status"] = "failed"
        inv["error_code"] = "UNAUTHORIZED"
        inv["error_message"] = "No active credential available"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", "Unauthorized")

    inv = _inv_base(client["id"], key["id"], {"limit": limit} if limit is not None else {})

    rpm = client.get("rate_limit_rpm")
    if not isinstance(rpm, int):
        rpm = 60
    if rpm < 1:
        rpm = 1
    if rpm > 6000:
        rpm = 6000
    tz_name = client.get("default_timezone") or "UTC"
    day_key = _client_day_key(now, tz_name)
    daily_quota = client.get("daily_quota_requests")
    if not isinstance(daily_quota, int):
        daily_quota = -1

    used_rpm = _count_rpm(invocations, client["id"], now)
    used_daily = _count_daily(invocations, client["id"], day_key, tz_name)

    if used_rpm >= rpm:
        inv["status"] = "rate_limited"
        inv["error_code"] = "RPM_EXCEEDED"
        inv["error_message"] = f"Rate limit exceeded ({rpm} rpm); please retry later"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", inv["error_message"], error_code=inv["error_code"])
    if daily_quota != -1 and used_daily >= daily_quota:
        inv["status"] = "rate_limited"
        inv["error_code"] = "DAILY_QUOTA_EXCEEDED"
        inv["error_message"] = f"Daily quota exceeded ({daily_quota} requests)"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("QUOTA_EXCEEDED", inv["error_message"], error_code=inv["error_code"])

    # Persist key last_used_at
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            k["last_used_at"] = _dt_iso(now)
            k["updated_at"] = _dt_iso(now)
            break
    _save("api_keys.json", api_keys)

    # Resolve data source by code; fallback by tool_name mapping.
    code_candidates = ["hupu_pedestrian_street_hotspots", "hupu_hotspots", "hupu_pedestrian_street"]
    sources = [s for s in data_sources if isinstance(s, dict) and s.get("code") in code_candidates]
    if not sources:
        sources = [s for s in data_sources if isinstance(s, dict) and s.get("category") == "hotspots"]

    def _src_rank(s):
        st = s.get("status")
        return 0 if st == "enabled" else (1 if st == "degraded" else 2)

    sources = sorted(sources, key=_src_rank)
    source = None
    for s in sources:
        if s.get("status") in ("enabled", "degraded"):
            source = s
            break
    if not source:
        inv["status"] = "failed"
        inv["error_code"] = "NO_SOURCE"
        inv["error_message"] = "No enabled/degraded hotspots data source available"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No available snapshot")

    cache_key = f"{source.get('code')}|default"

    def _fresh_snapshot():
        candidates = []
        for snp in fetch_snapshots:
            if not isinstance(snp, dict):
                continue
            if snp.get("source_id") != source.get("id"):
                continue
            if snp.get("cache_key") != cache_key:
                continue
            if snp.get("status") != "fresh":
                continue
            exp = _dt_parse(snp.get("expires_at"))
            if exp and exp > now:
                fetched = _dt_parse(snp.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
                candidates.append((fetched, snp))
        if not candidates:
            return None
        candidates.sort(key=lambda x: x[0], reverse=True)
        return candidates[0][1]

    def _best_stale_fallback():
        candidates = []
        for snp in fetch_snapshots:
            if not isinstance(snp, dict):
                continue
            if snp.get("source_id") != source.get("id"):
                continue
            if snp.get("cache_key") != cache_key:
                continue
            if snp.get("status") == "failed":
                continue
            items = snp.get("normalized_items")
            if not isinstance(items, list) or not items:
                continue
            fetched = _dt_parse(snp.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            candidates.append((fetched, snp))
        if not candidates:
            return None
        candidates.sort(key=lambda x: x[0], reverse=True)
        return candidates[0][1]

    snap = _fresh_snapshot()
    served_from_cache = True
    warning = None
    if not snap:
        snap = _best_stale_fallback()
        if snap:
            warning = "Serving stale snapshot (stale-while-revalidate); upstream fetch not available offline"
            if snap.get("status") == "fresh":
                snap["status"] = "stale"
                snap["updated_at"] = _dt_iso(now)
                _save("fetch_snapshots.json", fetch_snapshots)
        else:
            inv["status"] = "failed"
            inv["error_code"] = "NO_SNAPSHOT"
            inv["error_message"] = "No available snapshot"
            inv["latency_ms"] = int((_time.time() - t0) * 1000)
            inv["updated_at"] = _dt_iso(_now())
            invocations.append(inv)
            _save("tool_invocations.json", invocations)
            return _err("NOT_FOUND", "No available snapshot")

    items = snap.get("normalized_items")
    if not isinstance(items, list):
        items = []

    # Clamp limit to max_limit if configured
    max_limit = source.get("max_limit")
    default_limit = source.get("default_limit")
    if isinstance(max_limit, int) and max_limit > 0:
        if limit is None:
            if isinstance(default_limit, int) and default_limit > 0:
                use_limit = min(default_limit, max_limit)
            else:
                use_limit = max_limit
        else:
            use_limit = min(limit, max_limit)
    else:
        use_limit = limit if limit is not None else (default_limit if isinstance(default_limit, int) and default_limit > 0 else None)

    if use_limit is not None:
        items_out = items[: int(use_limit)]
    else:
        items_out = items

    inv["status"] = "served_from_cache" if served_from_cache else "fetched_live"
    inv["snapshot_ids"] = [snap.get("id")] if snap.get("id") else None
    if warning:
        inv["error_code"] = "STALE_CACHE"
        inv["error_message"] = warning
    inv["latency_ms"] = int((_time.time() - t0) * 1000)
    inv["updated_at"] = _dt_iso(_now())
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    return {
        "data": items_out,
        "meta": {
            "total": len(items),
            "returned": len(items_out),
            "limit_used": use_limit,
            "source_id": source.get("id"),
            "snapshot_id": snap.get("id"),
            "cache_key": cache_key,
            "served_from_cache": served_from_cache,
            "warning": warning,
        },
    }

def zhihu_realtime_hotspots(limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.perf_counter()
    invoked_at = _now()

    # Validate params (additionalProperties=false)
    if _extra:
        return _err("VALIDATION_ERROR", "Unknown parameter(s).", unknown_fields=sorted(list(_extra.keys())))
    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be a number.")
        if not (limit > 0):
            return _err("VALIDATION_ERROR", "limit must be greater than 0.")
        req_limit = int(limit)
        if req_limit <= 0:
            return _err("VALIDATION_ERROR", "limit must be greater than 0.")
    else:
        req_limit = None

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    data_sources = _load("data_sources.json")
    fetch_snapshots = _load("fetch_snapshots.json")
    tool_invocations = _load("tool_invocations.json")

    tool_name = "zhihu-realtime-hotspots"
    request_params = {}
    if limit is not None:
        request_params["limit"] = limit

    client_row = None
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        cid = k.get("client_id")
        if not cid:
            continue
        c = next((cc for cc in api_clients if isinstance(cc, dict) and cc.get("id") == cid), None)
        if not c or c.get("status") != "active":
            continue
        client_row = c
        key_row = k
        break

    def _log_invocation(status, snapshot_ids=None, error_code=None, error_message=None, latency_ms=None):
        inv_id = _gen_id("invk")
        rec = {
            "id": inv_id,
            "client_id": client_row.get("id") if client_row else "unknown",
            "api_key_id": key_row.get("id") if key_row else "unknown",
            "tool_name": tool_name,
            "request_params": request_params,
            "limit": float(limit) if limit is not None else None,
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": status,
            "snapshot_ids": snapshot_ids,
            "latency_ms": latency_ms,
            "error_code": error_code,
            "error_message": error_message,
            "invoked_at": _iso(invoked_at),
            "created_at": _iso(invoked_at),
            "updated_at": _iso(invoked_at),
        }
        tool_invocations.append(rec)
        _save("tool_invocations.json", tool_invocations)
        return rec

    if not client_row or not key_row:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log_invocation(
            status="failed",
            snapshot_ids=None,
            error_code="UNAUTHORIZED",
            error_message="No active api_key/api_client combination available for this call.",
            latency_ms=latency_ms,
        )
        return _err("UNAUTHORIZED", "Unauthorized.")

    # Rate limit & quota
    client_id = client_row["id"]
    rate_limit_rpm = client_row.get("rate_limit_rpm")
    daily_quota_requests = client_row.get("daily_quota_requests")

    if not isinstance(rate_limit_rpm, int) or rate_limit_rpm < 1 or rate_limit_rpm > 6000:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log_invocation(
            status="failed",
            snapshot_ids=None,
            error_code="VALIDATION_ERROR",
            error_message="Client rate_limit_rpm misconfigured.",
            latency_ms=latency_ms,
        )
        return _err("VALIDATION_ERROR", "Client configuration invalid (rate_limit_rpm).")

    now_dt = invoked_at
    one_min_ago = now_dt - datetime.timedelta(minutes=1)

    def _invoked_at_dt(r):
        return _parse_dt(r.get("invoked_at")) or _parse_dt(r.get("created_at"))

    recent = 0
    for r in tool_invocations:
        if not isinstance(r, dict):
            continue
        if r.get("client_id") != client_id:
            continue
        dt = _invoked_at_dt(r)
        if dt and dt > one_min_ago:
            recent += 1

    if recent >= rate_limit_rpm:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log_invocation(
            status="rate_limited",
            snapshot_ids=None,
            error_code="RATE_LIMIT",
            error_message="Rate limit exceeded.",
            latency_ms=latency_ms,
        )
        return _err("RATE_LIMIT", "Rate limit exceeded.", limit="rpm", rate_limit_rpm=rate_limit_rpm)

    if isinstance(daily_quota_requests, int) and daily_quota_requests != -1:
        tzname = client_row.get("default_timezone") or "UTC"
        try:
            tz = datetime.timezone.utc if tzname.upper() == "UTC" else datetime.timezone(datetime.timedelta(hours=int(tzname)))
        except Exception:
            tz = datetime.timezone.utc
        local_now = now_dt.astimezone(tz)
        local_day_start = local_now.replace(hour=0, minute=0, second=0, microsecond=0)
        day_start_utc = local_day_start.astimezone(datetime.timezone.utc)

        day_count = 0
        for r in tool_invocations:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id:
                continue
            dt = _invoked_at_dt(r)
            if dt and dt >= day_start_utc:
                day_count += 1

        if day_count >= daily_quota_requests:
            latency_ms = int((time.perf_counter() - t0) * 1000)
            _log_invocation(
                status="rate_limited",
                snapshot_ids=None,
                error_code="QUOTA_EXCEEDED",
                error_message="Daily quota exceeded.",
                latency_ms=latency_ms,
            )
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded.", daily_quota_requests=daily_quota_requests)

    source = next((s for s in data_sources if isinstance(s, dict) and s.get("code") == "zhihu_realtime_hotspots"), None)
    if not source:
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log_invocation(
            status="failed",
            snapshot_ids=None,
            error_code="NOT_FOUND",
            error_message="Data source not configured.",
            latency_ms=latency_ms,
        )
        return _err("NOT_FOUND", "Data source not found.")
    if source.get("status") == "disabled":
        latency_ms = int((time.perf_counter() - t0) * 1000)
        _log_invocation(
            status="failed",
            snapshot_ids=None,
            error_code="NOT_FOUND",
            error_message="Data source is disabled.",
            latency_ms=latency_ms,
        )
        return _err("NOT_FOUND", "No snapshot available.")

    source_id = source.get("id")
    cache_key = "zhihu_realtime_hotspots|default"

    max_limit = source.get("max_limit")
    default_limit = source.get("default_limit")
    use_limit = req_limit
    if use_limit is None:
        use_limit = int(default_limit) if isinstance(default_limit, int) and default_limit >= 1 else None
    if use_limit is None:
        use_limit = 10
    if isinstance(max_limit, int) and max_limit >= 1 and use_limit > max_limit:
        use_limit = max_limit

    now_dt = _now()
    candidates = []
    for snap in fetch_snapshots:
        if not isinstance(snap, dict):
            continue
        if snap.get("source_id") != source_id:
            continue
        if snap.get("cache_key") != cache_key:
            continue
        if snap.get("status") != "fresh":
            continue
        exp = _parse_dt(snap.get("expires_at"))
        if exp and exp > now_dt:
            candidates.append(snap)

    def _fetched_at(s):
        return _parse_dt(s.get("fetched_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    snapshot = max(candidates, key=_fetched_at) if candidates else None

    # Update key last_used_at
    key_row["last_used_at"] = _iso(invoked_at)
    key_row["updated_at"] = _iso(invoked_at)
    _save("api_keys.json", api_keys)

    if snapshot:
        items = snapshot.get("normalized_items") or []
        if not isinstance(items, list):
            items = []
        items_out = items[:use_limit]
        latency_ms = int((time.perf_counter() - t0) * 1000)
        inv = _log_invocation(
            status="served_from_cache",
            snapshot_ids=[snapshot.get("id")],
            error_code=None,
            error_message=None,
            latency_ms=latency_ms,
        )
        return {
            "tool_name": tool_name,
            "status": inv["status"],
            "from_cache": True,
            "source": {"id": source_id, "code": source.get("code"), "display_name": source.get("display_name")},
            "cache_key": cache_key,
            "snapshot_id": snapshot.get("id"),
            "fetched_at": snapshot.get("fetched_at"),
            "expires_at": snapshot.get("expires_at"),
            "limit": use_limit,
            "total_items": len(items),
            "items": items_out,
        }

    older = []
    for snap in fetch_snapshots:
        if not isinstance(snap, dict):
            continue
        if snap.get("source_id") != source_id or snap.get("cache_key") != cache_key:
            continue
        if snap.get("status") not in ("fresh", "stale"):
            continue
        older.append(snap)
    fallback = max(older, key=_fetched_at) if older else None
    if fallback:
        if fallback.get("status") == "fresh":
            fallback["status"] = "stale"
            fallback["updated_at"] = _iso(now_dt)
            _save("fetch_snapshots.json", fetch_snapshots)

        items = fallback.get("normalized_items") or []
        if not isinstance(items, list):
            items = []
        items_out = items[:use_limit]
        latency_ms = int((time.perf_counter() - t0) * 1000)
        inv = _log_invocation(
            status="served_from_cache",
            snapshot_ids=[fallback.get("id")],
            error_code=None,
            error_message="Serving stale snapshot (stale-while-revalidate).",
            latency_ms=latency_ms,
        )
        return {
            "tool_name": tool_name,
            "status": inv["status"],
            "from_cache": True,
            "stale": True,
            "warning": "Serving stale snapshot (stale-while-revalidate).",
            "source": {"id": source_id, "code": source.get("code"), "display_name": source.get("display_name")},
            "cache_key": cache_key,
            "snapshot_id": fallback.get("id"),
            "fetched_at": fallback.get("fetched_at"),
            "expires_at": fallback.get("expires_at"),
            "limit": use_limit,
            "total_items": len(items),
            "items": items_out,
        }

    latency_ms = int((time.perf_counter() - t0) * 1000)
    _log_invocation(
        status="failed",
        snapshot_ids=None,
        error_code="NOT_FOUND",
        error_message="No available snapshot (upstream fetch failed or never succeeded).",
        latency_ms=latency_ms,
    )
    return _err("NOT_FOUND", "No snapshot available.")

def bilibili_daily_hotspots(limit=None, **_extra):
    import json, os, datetime, uuid, time as _time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"pulse_{prefix}_{uuid.uuid4().hex}"

    TOOL_NAME = "bilibili-daily-hotspots"
    t0 = _time.time()
    now = _now_utc()

    if _extra:
        return _err("VALIDATION_ERROR", "Unknown parameters", unknown=list(_extra.keys()))
    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool) or limit <= 0:
            return _err("VALIDATION_ERROR", "limit must be a positive number")
        limit = int(limit)

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    data_sources = _load("data_sources.json")
    fetch_snapshots = _load("fetch_snapshots.json")
    invocations = _load("tool_invocations.json")

    client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}

    def _pick_auth():
        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            c = client_by_id.get(k.get("client_id"))
            if c and c.get("status") == "active":
                return c, k
        return None, None

    client, key = _pick_auth()
    if not client or not key:
        return _err("UNAUTHORIZED", "Unauthorized")

    def _inv_row(status, request_params, snapshot_ids=None, error_code=None, error_message=None, latency_ms=None):
        now2 = _now_utc()
        return {
            "id": _gen_id("inv"),
            "client_id": client.get("id"),
            "api_key_id": key.get("id"),
            "tool_name": TOOL_NAME,
            "request_params": request_params,
            "limit": request_params.get("limit"),
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": status,
            "snapshot_ids": snapshot_ids,
            "latency_ms": latency_ms,
            "error_code": error_code,
            "error_message": error_message,
            "invoked_at": _dt_iso(now2),
            "created_at": _dt_iso(now2),
            "updated_at": _dt_iso(now2),
        }

    def _count_rpm(client_id):
        window_start = now - datetime.timedelta(seconds=60)
        n = 0
        for r in invocations:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            t = _dt_parse(r.get("invoked_at"))
            if t and window_start < t <= now:
                n += 1
        return n

    def _count_daily(client_id, tz_name):
        off_minutes = 0
        if isinstance(tz_name, str) and tz_name:
            s = tz_name.strip()
            if (s.startswith("+") or s.startswith("-")) and len(s) >= 6 and s[3] == ":":
                try:
                    sign = 1 if s[0] == "+" else -1
                    hh = int(s[1:3]); mm = int(s[4:6])
                    off_minutes = sign * (hh * 60 + mm)
                except Exception:
                    off_minutes = 0
        local_now = now + datetime.timedelta(minutes=off_minutes)
        day = local_now.date()
        n = 0
        for r in invocations:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            t = _dt_parse(r.get("invoked_at"))
            if not t:
                continue
            local_t = t + datetime.timedelta(minutes=off_minutes)
            if local_t.date() == day:
                n += 1
        return n

    rpm_limit = client.get("rate_limit_rpm")
    daily_quota = client.get("daily_quota_requests")
    if not isinstance(rpm_limit, int) or rpm_limit < 1:
        rpm_limit = 60
    if not isinstance(daily_quota, int):
        daily_quota = -1

    req_params = {} if limit is None else {"limit": limit}
    if _count_rpm(client.get("id")) >= rpm_limit:
        inv = _inv_row(
            "rate_limited",
            req_params,
            snapshot_ids=None,
            error_code="RPM_EXCEEDED",
            error_message=f"Rate limit exceeded ({rpm_limit} rpm); please retry later",
            latency_ms=int((_time.time() - t0) * 1000),
        )
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=30)

    tz_name = client.get("default_timezone") or "UTC"
    if daily_quota != -1 and _count_daily(client.get("id"), tz_name) >= daily_quota:
        inv = _inv_row(
            "rate_limited",
            req_params,
            snapshot_ids=None,
            error_code="DAILY_QUOTA_EXCEEDED",
            error_message=f"Daily quota exceeded ({daily_quota}); please retry tomorrow",
            latency_ms=int((_time.time() - t0) * 1000),
        )
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # Find Bilibili source
    candidates = []
    for s in data_sources:
        if not isinstance(s, dict):
            continue
        code = (s.get("code") or "").lower()
        dn = (s.get("display_name") or "").lower()
        if "bilibili" in code or "bilibili" in dn or "哔哩" in (s.get("display_name") or ""):
            if s.get("category") == "hotspots":
                candidates.append(s)

    def _src_rank(s):
        st = s.get("status")
        return 0 if st == "enabled" else (1 if st == "degraded" else 2)

    candidates.sort(key=_src_rank)
    source = candidates[0] if candidates else None
    if not source:
        inv = _inv_row(
            "failed",
            req_params,
            snapshot_ids=None,
            error_code="SOURCE_NOT_FOUND",
            error_message="Data source not found",
            latency_ms=int((_time.time() - t0) * 1000),
        )
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No available snapshot")

    cache_key = f"{source.get('code')}|default"

    fresh = []
    for snp in fetch_snapshots:
        if not isinstance(snp, dict):
            continue
        if snp.get("source_id") != source.get("id") or snp.get("cache_key") != cache_key:
            continue
        if snp.get("status") != "fresh":
            continue
        exp = _dt_parse(snp.get("expires_at"))
        if exp and exp > now:
            fresh.append(snp)
    fresh.sort(key=lambda r: (_dt_parse(r.get("fetched_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
    chosen = fresh[0] if fresh else None

    warning = None
    if not chosen:
        candidates_s = []
        for snp in fetch_snapshots:
            if not isinstance(snp, dict):
                continue
            if snp.get("source_id") != source.get("id") or snp.get("cache_key") != cache_key:
                continue
            if snp.get("status") == "failed":
                continue
            candidates_s.append(snp)
        candidates_s.sort(key=lambda r: (_dt_parse(r.get("fetched_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
        if candidates_s:
            chosen = candidates_s[0]
            exp = _dt_parse(chosen.get("expires_at"))
            if exp and exp <= now and chosen.get("status") == "fresh":
                chosen["status"] = "stale"
                chosen["updated_at"] = _dt_iso(now)
                warning = "Snapshot expired; served stale cache (stale-while-revalidate)"
                _save("fetch_snapshots.json", fetch_snapshots)

    if not chosen:
        inv = _inv_row(
            "failed",
            req_params,
            snapshot_ids=None,
            error_code="NO_SNAPSHOT",
            error_message="Upstream failed and no cached snapshot available",
            latency_ms=int((_time.time() - t0) * 1000),
        )
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No available snapshot")

    items = chosen.get("normalized_items")
    if not isinstance(items, list):
        items = []

    max_limit = source.get("max_limit")
    default_limit = source.get("default_limit")
    server_limit = limit
    if server_limit is None and isinstance(default_limit, int) and default_limit >= 1:
        server_limit = default_limit
    if server_limit is None:
        server_limit = len(items) if items else 0
    if isinstance(max_limit, int) and max_limit >= 1:
        server_limit = min(server_limit, max_limit)
    result_items = [it for it in items if isinstance(it, dict)][:max(0, server_limit)]

    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            k["last_used_at"] = _dt_iso(now)
            k["updated_at"] = _dt_iso(now)
            break
    _save("api_keys.json", api_keys)

    inv = _inv_row(
        "served_from_cache",
        req_params,
        snapshot_ids=[chosen.get("id")],
        error_code="STALE_CACHE" if warning else None,
        error_message=warning,
        latency_ms=int((_time.time() - t0) * 1000),
    )
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    return {
        "items": result_items,
        "count": len(result_items),
        "snapshot_id": chosen.get("id"),
        "source_id": source.get("id"),
        "cache_key": cache_key,
        "limit": server_limit,
        "warning": warning,
    }

