        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _inv_row_base(client_id, api_key_id, tool_name, request_params):
        now = _now()
        return {
            "id": _gen_id("inv"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": tool_name,
            "request_params": request_params,
            "limit": request_params.get("limit", None),
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "received",
            "snapshot_ids": None,
            "latency_ms": None,
            "error_code": None,
            "error_message": None,
            "invoked_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }

    def _pick_auth_context():
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        # Ambient auth: find any usable active api_key + active client
        active_clients = {c.get("id"): c for c in clients if c.get("status") == "active" and isinstance(c.get("id"), str)}
        for k in keys:
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            if cid in active_clients:
                return active_clients[cid], k
        return None, None

    def _enforce_limits(client_row, api_key_row, tool_name, request_params):
        invocations = _load("tool_invocations.json")
        now = _now()

        rate_limit_rpm = client_row.get("rate_limit_rpm")
        daily_quota = client_row.get("daily_quota_requests")

        # Validate client config types; if corrupted, treat as unauthorized-capability missing
        if not isinstance(rate_limit_rpm, int) or rate_limit_rpm < 1 or rate_limit_rpm > 6000:
            return False, "UNAUTHORIZED", "client rate_limit_rpm invalid"
        if not isinstance(daily_quota, int) or not (daily_quota == -1 or daily_quota >= 0):
            return False, "UNAUTHORIZED", "client daily_quota_requests invalid"

        # Sliding window for rpm: last 60 seconds
        window_start = now - datetime.timedelta(seconds=60)
        cnt_60s = 0
        for r in invocations:
            if r.get("client_id") != client_row.get("id"):
                continue
            t = _parse_dt(r.get("invoked_at"))
            if t is None:
                continue
            if t > window_start and t <= now:
                cnt_60s += 1
        if cnt_60s >= rate_limit_rpm:
            return False, "RATE_LIMIT", "rate limit exceeded"

        # Daily quota (UTC day, since we don't have timezone lib; use UTC boundaries)
        if daily_quota != -1:
            day_start = now.replace(hour=0, minute=0, second=0, microsecond=0)
            cnt_day = 0
            for r in invocations:
                if r.get("client_id") != client_row.get("id"):
                    continue
                t = _parse_dt(r.get("invoked_at"))
                if t is None:
                    continue
                if t >= day_start and t <= now:
                    cnt_day += 1
            if cnt_day >= daily_quota:
                return False, "QUOTA_EXCEEDED", "daily quota exceeded"

        return True, None, None

    start = time.perf_counter()
    tool_name = "huxiu-hotspots"

    # JSON-schema: additionalProperties=false. Tool signature only includes 'limit', but reject unknown extras.
    if _extra:
        # Still must attempt to auth to record invocation as failed with correct FK fields; if cannot, return UNAUTHORIZED.
        client_row, api_key_row = _pick_auth_context()
        if client_row and api_key_row:
            invocations = _load("tool_invocations.json")
            inv = _inv_row_base(client_row["id"], api_key_row["id"], tool_name, {})
            inv["status"] = "failed"
            inv["error_code"] = "VALIDATION_ERROR"
            inv["error_message"] = "unknown fields are not allowed"
            inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
            inv["updated_at"] = _iso(_now())
            invocations.append(inv)
            _save("tool_invocations.json", invocations)
        return _err("VALIDATION_ERROR", "unknown fields are not allowed", fields=list(_extra.keys()))

    # Validate limit
    req_params = {}
    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            # record failed invocation if possible
            client_row, api_key_row = _pick_auth_context()
            if client_row and api_key_row:
                invocations = _load("tool_invocations.json")
                inv = _inv_row_base(client_row["id"], api_key_row["id"], tool_name, {"limit": limit})
                inv["status"] = "failed"
                inv["error_code"] = "VALIDATION_ERROR"
                inv["error_message"] = "limit must be a number"
                inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
                inv["updated_at"] = _iso(_now())
                invocations.append(inv)
                _save("tool_invocations.json", invocations)
            return _err("VALIDATION_ERROR", "limit must be a number")
        if limit <= 0:
            client_row, api_key_row = _pick_auth_context()
            if client_row and api_key_row:
                invocations = _load("tool_invocations.json")
                inv = _inv_row_base(client_row["id"], api_key_row["id"], tool_name, {"limit": limit})
                inv["status"] = "failed"
                inv["error_code"] = "VALIDATION_ERROR"
                inv["error_message"] = "limit must be > 0"
                inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
                inv["updated_at"] = _iso(_now())
                invocations.append(inv)
                _save("tool_invocations.json", invocations)
            return _err("VALIDATION_ERROR", "limit must be > 0")
        req_params["limit"] = float(limit) if isinstance(limit, float) else int(limit)

    # Authenticate (ambient)
    client_row, api_key_row = _pick_auth_context()
    if not client_row or not api_key_row:
        # Cannot record tool_invocations due to FK; return UNAUTHORIZED.
        return _err("UNAUTHORIZED", "no active api key / client available")

    # Quota / rate limit check (must still record invocation as rate_limited)
    ok, ecode, emsg = _enforce_limits(client_row, api_key_row, tool_name, req_params)
    if not ok and ecode in ("RATE_LIMIT", "QUOTA_EXCEEDED"):
        invocations = _load("tool_invocations.json")
        inv = _inv_row_base(client_row["id"], api_key_row["id"], tool_name, dict(req_params))
        inv["status"] = "rate_limited"
        inv["error_code"] = ecode
        inv["error_message"] = emsg
        inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
        inv["updated_at"] = _iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err(ecode, emsg)

    if not ok and ecode == "UNAUTHORIZED":
        invocations = _load("tool_invocations.json")
        inv = _inv_row_base(client_row["id"], api_key_row["id"], tool_name, dict(req_params))
        inv["status"] = "failed"
        inv["error_code"] = "UNAUTHORIZED"
        inv["error_message"] = emsg
        inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
        inv["updated_at"] = _iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", emsg)

    # Resolve data source
    data_sources = _load("data_sources.json")
    source = None
    for s in data_sources:
        if s.get("code") == "huxiu_hotspots":
            source = s
            break
    if not source:
        invocations = _load("tool_invocations.json")
        inv = _inv_row_base(client_row["id"], api_key_row["id"], tool_name, dict(req_params))
        inv["status"] = "failed"
        inv["error_code"] = "NOT_FOUND"
        inv["error_message"] = "data source not configured"
        inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
        inv["updated_at"] = _iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "data source not configured")

    if source.get("status") == "disabled":
        invocations = _load("tool_invocations.json")
        inv = _inv_row_base(client_row["id"], api_key_row["id"], tool_name, dict(req_params))
        inv["status"] = "failed"
        inv["error_code"] = "UPSTREAM_ERROR"
        inv["error_message"] = "data source disabled"
        inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
        inv["updated_at"] = _iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UPSTREAM_ERROR", "upstream unavailable")

    cache_key = "huxiu_hotspots|default"

    # Find latest fresh unexpired snapshot for (source_id, cache_key)
    snapshots = _load("fetch_snapshots.json")
    now = _now()
    candidates = []
    for snap in snapshots:
        if snap.get("source_id") != source.get("id"):
            continue
        if snap.get("cache_key") != cache_key:
            continue
        if snap.get("status") != "fresh":
            continue
        exp = _parse_dt(snap.get("expires_at"))
        if exp is None or exp <= now:
            continue
        fetched = _parse_dt(snap.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        candidates.append((fetched, snap))
    candidates.sort(key=lambda x: x[0], reverse=True)
    snap = candidates[0][1] if candidates else None

    invocations = _load("tool_invocations.json")
    inv = _inv_row_base(client_row["id"], api_key_row["id"], tool_name, dict(req_params))

    # Update api_key last_used_at
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys)

    if not snap:
        inv["status"] = "failed"
        inv["error_code"] = "UPSTREAM_ERROR"
        inv["error_message"] = "no available snapshot"
        inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
        inv["updated_at"] = _iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UPSTREAM_ERROR", "upstream unavailable and no cached snapshot")

    inv["status"] = "served_from_cache"
    inv["snapshot_ids"] = [snap.get("id")]
    inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
    inv["updated_at"] = _iso(_now())
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    items = snap.get("normalized_items") or []
    if not isinstance(items, list):
        items = []

    # Clamp limit to data_source.max_limit if set; then apply request limit if provided.
    max_limit = source.get("max_limit")
    used_limit = None
    if isinstance(max_limit, int) and max_limit >= 1:
        used_limit = max_limit
    if limit is not None:
        req_lim = int(limit) if isinstance(limit, int) else int(float(limit))
        used_limit = req_lim if used_limit is None else min(used_limit, req_lim)

    if used_limit is not None:
        items = items[: max(0, used_limit)]

    return {
        "tool": tool_name,
        "source": {"id": source.get("id"), "code": source.get("code"), "display_name": source.get("display_name")},
        "cache": {
            "snapshot_id": snap.get("id"),
            "cache_key": cache_key,
            "status": snap.get("status"),
            "fetched_at": snap.get("fetched_at"),
            "expires_at": snap.get("expires_at"),
        },
        "params": {"limit": (int(limit) if isinstance(limit, (int, float)) and limit is not None else None)},
        "count": len(items),
        "items": items,
    }

