        inv["error_code"] = "NOT_FOUND"
        inv["error_message"] = "data source not configured"
        inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
        inv["updated_at"] = _iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "data source not configured")

    if source.get("status") == "disabled":
        invocations = _load("tool_invocations.json")
        inv = _inv_row_base(client_row["id"], api_key_row["id"], tool_name, dict(req_params))
        inv["status"] = "failed"
        inv["error_code"] = "UPSTREAM_ERROR"
        inv["error_message"] = "data source disabled"
        inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
        inv["updated_at"] = _iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UPSTREAM_ERROR", "upstream unavailable")

    cache_key = "product_manager_hotspots|default"

    snapshots = _load("fetch_snapshots.json")
    now = _now()
    candidates = []
    for snap in snapshots:
        if snap.get("source_id") != source.get("id"):
            continue
        if snap.get("cache_key") != cache_key:
            continue
        if snap.get("status") != "fresh":
            continue
        exp = _parse_dt(snap.get("expires_at"))
        if exp is None or exp <= now:
            continue
        fetched = _parse_dt(snap.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        candidates.append((fetched, snap))
    candidates.sort(key=lambda x: x[0], reverse=True)
    snap = candidates[0][1] if candidates else None

    invocations = _load("tool_invocations.json")
    inv = _inv_row_base(client_row["id"], api_key_row["id"], tool_name, dict(req_params))

    api_keys = _load("api_keys.json")
    for k in api_keys:
        if k.get("id") == api_key_row.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            break
    _save("api_keys.json", api_keys)

    if not snap:
        inv["status"] = "failed"
        inv["error_code"] = "UPSTREAM_ERROR"
        inv["error_message"] = "no available snapshot"
        inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
        inv["updated_at"] = _iso(_now())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UPSTREAM_ERROR", "upstream unavailable and no cached snapshot")

    inv["status"] = "served_from_cache"
    inv["snapshot_ids"] = [snap.get("id")]
    inv["latency_ms"] = max(0, int((time.perf_counter() - start) * 1000))
    inv["updated_at"] = _iso(_now())
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    items = snap.get("normalized_items") or []
    if not isinstance(items, list):
        items = []

    max_limit = source.get("max_limit")
    used_limit = None
    if isinstance(max_limit, int) and max_limit >= 1:
        used_limit = max_limit
    if limit is not None:
        req_lim = int(limit) if isinstance(limit, int) else int(float(limit))
        used_limit = req_lim if used_limit is None else min(used_limit, req_lim)

    if used_limit is not None:
        items = items[: max(0, used_limit)]

    return {
        "tool": tool_name,
        "source": {"id": source.get("id"), "code": source.get("code"), "display_name": source.get("display_name")},
        "cache": {
            "snapshot_id": snap.get("id"),
            "cache_key": cache_key,
            "status": snap.get("status"),
            "fetched_at": snap.get("fetched_at"),
            "expires_at": snap.get("expires_at"),
        },
        "params": {"limit": (int(limit) if isinstance(limit, (int, float)) and limit is not None else None)},
        "count": len(items),
        "items": items,
    }

def in_information_hotspots(limit=None, **_extra):
    import json, os, datetime, uuid, time as _time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"pulse_{prefix}_{uuid.uuid4().hex}"

    TOOL_NAME = "in-information-hotspots"
    t0 = _time.time()
    now = _now_utc()

    if _extra:
        return _err("VALIDATION_ERROR", "Unknown parameters", unknown=list(_extra.keys()))
    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool) or limit <= 0:
            return _err("VALIDATION_ERROR", "limit must be a positive number")
        limit = int(limit)

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    data_sources = _load("data_sources.json")
    fetch_snapshots = _load("fetch_snapshots.json")
    invocations = _load("tool_invocations.json")

    client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}

    def _pick_auth():
        for k in api_keys:
            if not isinstance(k, dict) or k.get("status") != "active":
                continue
            c = client_by_id.get(k.get("client_id"))
            if c and c.get("status") == "active":
                return c, k
        return None, None

    client, key = _pick_auth()
    if not client or not key:
        return _err("UNAUTHORIZED", "Unauthorized")

    def _inv_row(status, request_params, snapshot_ids=None, error_code=None, error_message=None, latency_ms=None):
        now2 = _now_utc()
        return {
            "id": _gen_id("inv"),
            "client_id": client.get("id"),
            "api_key_id": key.get("id"),
            "tool_name": TOOL_NAME,
            "request_params": request_params,
            "limit": request_params.get("limit"),
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": status,
            "snapshot_ids": snapshot_ids,
            "latency_ms": latency_ms,
            "error_code": error_code,
            "error_message": error_message,
            "invoked_at": _dt_iso(now2),
            "created_at": _dt_iso(now2),
            "updated_at": _dt_iso(now2),
        }

    def _count_rpm(client_id):
        window_start = now - datetime.timedelta(seconds=60)
        n = 0
        for r in invocations:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            t = _dt_parse(r.get("invoked_at"))
            if t and window_start < t <= now:
                n += 1
        return n

    def _count_daily(client_id, tz_name):
        off_minutes = 0
        if isinstance(tz_name, str) and tz_name:
            s = tz_name.strip()
            if (s.startswith("+") or s.startswith("-")) and len(s) >= 6 and s[3] == ":":
                try:
                    sign = 1 if s[0] == "+" else -1
                    hh = int(s[1:3]); mm = int(s[4:6])
                    off_minutes = sign * (hh * 60 + mm)
                except Exception:
                    off_minutes = 0
        local_now = now + datetime.timedelta(minutes=off_minutes)
        day = local_now.date()
        n = 0
        for r in invocations:
            if not isinstance(r, dict) or r.get("client_id") != client_id:
                continue
            t = _dt_parse(r.get("invoked_at"))
            if not t:
                continue
            local_t = t + datetime.timedelta(minutes=off_minutes)
            if local_t.date() == day:
                n += 1
        return n

    rpm_limit = client.get("rate_limit_rpm")
    daily_quota = client.get("daily_quota_requests")
    if not isinstance(rpm_limit, int) or rpm_limit < 1:
        rpm_limit = 60
    if not isinstance(daily_quota, int):
        daily_quota = -1

    req_params = {} if limit is None else {"limit": limit}
    if _count_rpm(client.get("id")) >= rpm_limit:
        inv = _inv_row(
            "rate_limited",
            req_params,
            snapshot_ids=None,
            error_code="RPM_EXCEEDED",
            error_message=f"Rate limit exceeded ({rpm_limit} rpm); please retry later",
            latency_ms=int((_time.time() - t0) * 1000),
        )
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("RATE_LIMIT", "Rate limit exceeded", retry_after_seconds=30)

    tz_name = client.get("default_timezone") or "UTC"
    if daily_quota != -1 and _count_daily(client.get("id"), tz_name) >= daily_quota:
        inv = _inv_row(
            "rate_limited",
            req_params,
            snapshot_ids=None,
            error_code="DAILY_QUOTA_EXCEEDED",
            error_message=f"Daily quota exceeded ({daily_quota}); please retry tomorrow",
            latency_ms=int((_time.time() - t0) * 1000),
        )
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded")

    # Find IT-information source (code/display_name heuristics)
    candidates = []
    for s in data_sources:
        if not isinstance(s, dict):
            continue
        if s.get("category") != "hotspots":
            continue
        code = (s.get("code") or "").lower()
        dn = (s.get("display_name") or "").lower()
        if "it" in code and ("information" in code or "news" in code) or "it资讯" in (s.get("display_name") or "") or "it" in dn and ("资讯" in (s.get("display_name") or "") or "information" in dn):
            candidates.append(s)
    if not candidates:
        # fallback: match "in_information" fragments
        for s in data_sources:
            if not isinstance(s, dict) or s.get("category") != "hotspots":
                continue
            code = (s.get("code") or "").lower()
            if "in_information" in code or "information_hotspots" in code:
                candidates.append(s)

    def _src_rank(s):
        st = s.get("status")
        return 0 if st == "enabled" else (1 if st == "degraded" else 2)

    candidates.sort(key=_src_rank)
    source = candidates[0] if candidates else None
    if not source:
        inv = _inv_row(
            "failed",
            req_params,
            snapshot_ids=None,
            error_code="SOURCE_NOT_FOUND",
            error_message="Data source not found",
            latency_ms=int((_time.time() - t0) * 1000),
        )
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Data source not found")

    cache_key = f"{source.get('code')}|default"

    fresh = []
    for snp in fetch_snapshots:
        if not isinstance(snp, dict):
            continue
        if snp.get("source_id") != source.get("id") or snp.get("cache_key") != cache_key:
            continue
        if snp.get("status") != "fresh":
            continue
        exp = _dt_parse(snp.get("expires_at"))
        if exp and exp > now:
            fresh.append(snp)
    fresh.sort(key=lambda r: (_dt_parse(r.get("fetched_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
    chosen = fresh[0] if fresh else None

    warning = None
    if not chosen:
        candidates_s = []
        for snp in fetch_snapshots:
            if not isinstance(snp, dict):
                continue
            if snp.get("source_id") != source.get("id") or snp.get("cache_key") != cache_key:
                continue
            if snp.get("status") == "failed":
                continue
            candidates_s.append(snp)
        candidates_s.sort(key=lambda r: (_dt_parse(r.get("fetched_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)), reverse=True)
        if candidates_s:
            chosen = candidates_s[0]
            exp = _dt_parse(chosen.get("expires_at"))
            if exp and exp <= now and chosen.get("status") == "fresh":
                chosen["status"] = "stale"
                chosen["updated_at"] = _dt_iso(now)
                warning = "Snapshot expired; served stale cache (stale-while-revalidate)"
                _save("fetch_snapshots.json", fetch_snapshots)

    if not chosen:
        inv = _inv_row(
            "failed",
            req_params,
            snapshot_ids=None,
            error_code="UPSTREAM_UNAVAILABLE",
            error_message="Upstream unavailable and no cached snapshot available",
            latency_ms=int((_time.time() - t0) * 1000),
        )
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "No available snapshot")

    items = chosen.get("normalized_items")
    if not isinstance(items, list):
        items = []

    max_limit = source.get("max_limit")
    default_limit = source.get("default_limit")
    server_limit = limit
    if server_limit is None and isinstance(default_limit, int) and default_limit >= 1:
        server_limit = default_limit
    if server_limit is None:
        server_limit = len(items) if items else 0
    if isinstance(max_limit, int) and max_limit >= 1:
        server_limit = min(server_limit, max_limit)
    result_items = [it for it in items if isinstance(it, dict)][:max(0, server_limit)]

    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key.get("id"):
            k["last_used_at"] = _dt_iso(now)
            k["updated_at"] = _dt_iso(now)
            break
    _save("api_keys.json", api_keys)

    inv = _inv_row(
        "served_from_cache",
        req_params,
        snapshot_ids=[chosen.get("id")],
        error_code="STALE_CACHE" if warning else None,
        error_message=warning,
        latency_ms=int((_time.time() - t0) * 1000),
    )
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    return {
        "items": result_items,
        "count": len(result_items),
        "snapshot_id": chosen.get("id"),
        "source_id": source.get("id"),
        "cache_key": cache_key,
        "limit": server_limit,
        "warning": warning,
    }

def insect_hotspots(limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _clamp_limit(requested, ds_row):
        max_limit = ds_row.get("max_limit")
        if requested is None:
            requested = ds_row.get("default_limit")
        if requested is None:
            return None
        try:
            val = float(requested)
        except Exception:
            return "bad"
        if not (val > 0):
            return "bad"
        val_i = int(val)
        if val_i <= 0:
            val_i = 1
        if isinstance(max_limit, int) and max_limit >= 1:
            val_i = min(val_i, max_limit)
        return val_i

    def _resolve_auth_any_active():
        clients = _load("api_clients.json")
        keys = _load("api_keys.json")
        active_clients = {c["id"]: c for c in clients if c.get("status") == "active"}
        for k in keys:
            if k.get("status") != "active":
                continue
            cid = k.get("client_id")
            if cid in active_clients:
                return active_clients[cid], k
        return None, None

    def _minute_bucket(now_dt):
        return now_dt.strftime("%Y-%m-%dT%H:%M")

    def _day_bucket(now_dt):
        return now_dt.strftime("%Y-%m-%d")

    def _count_usage(invocations, client_id, now_dt):
        minute_key = _minute_bucket(now_dt)
        day_key = _day_bucket(now_dt)
        rpm = 0
        daily = 0
        for r in invocations:
            if r.get("client_id") != client_id:
                continue
            ia = _parse_dt(r.get("invoked_at") or r.get("created_at"))
            if ia is None:
                continue
            if _minute_bucket(ia) == minute_key:
                rpm += 1
            if _day_bucket(ia) == day_key:
                daily += 1
        return rpm, daily

    def _log_invocation(invocations, row):
        invocations.append(row)
        _save("tool_invocations.json", invocations)

    t0 = time.time()
    now = _now_utc()

    if limit is not None:
        if not isinstance(limit, (int, float)) or isinstance(limit, bool):
            return _err("VALIDATION_ERROR", "limit must be a number > 0")
        if not (float(limit) > 0):
            return _err("VALIDATION_ERROR", "limit must be > 0")

    client, key = _resolve_auth_any_active()
    invocations = _load("tool_invocations.json")

    if client is None or key is None:
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "client_id": "unknown",
            "api_key_id": "unknown",
            "tool_name": "insect-hotspots",
            "request_params": {"limit": limit} if limit is not None else {},
            "limit": float(limit) if limit is not None else None,
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "failed",
            "snapshot_ids": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "UNAUTHORIZED",
            "error_message": "No active api_key/api_client available for ambient authentication",
            "invoked_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _log_invocation(invocations, inv_row)
        return _err("UNAUTHORIZED", "Unauthorized")

    rpm_limit = client.get("rate_limit_rpm")
    daily_quota = client.get("daily_quota_requests")
    rpm_used, daily_used = _count_usage(invocations, client["id"], now)

    if isinstance(rpm_limit, int) and rpm_limit >= 1 and (rpm_used + 1) > rpm_limit:
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "client_id": client["id"],
            "api_key_id": key["id"],
            "tool_name": "insect-hotspots",
            "request_params": {"limit": limit} if limit is not None else {},
            "limit": float(limit) if limit is not None else None,
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "rate_limited",
            "snapshot_ids": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "RATE_LIMIT",
            "error_message": "Rate limit exceeded",
            "invoked_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _log_invocation(invocations, inv_row)
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_rpm=rpm_limit)

    if isinstance(daily_quota, int) and daily_quota != -1 and (daily_used + 1) > daily_quota:
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "client_id": client["id"],
            "api_key_id": key["id"],
            "tool_name": "insect-hotspots",
            "request_params": {"limit": limit} if limit is not None else {},
            "limit": float(limit) if limit is not None else None,
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "rate_limited",
            "snapshot_ids": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "QUOTA_EXCEEDED",
            "error_message": "Daily quota exceeded",
            "invoked_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _log_invocation(invocations, inv_row)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", daily_quota=daily_quota)

    sources = _load("data_sources.json")
    ds = None
    for s in sources:
        if s.get("code") == "insect_hotspots":
            ds = s
            break
    if ds is None:
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "client_id": client["id"],
            "api_key_id": key["id"],
            "tool_name": "insect-hotspots",
            "request_params": {"limit": limit} if limit is not None else {},
            "limit": float(limit) if limit is not None else None,
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "failed",
            "snapshot_ids": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "UPSTREAM_ERROR",
            "error_message": "Data source not configured",
            "invoked_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _log_invocation(invocations, inv_row)
        return _err("NOT_FOUND", "Data source not found")

    eff_limit = _clamp_limit(limit, ds)
    if eff_limit == "bad":
        return _err("VALIDATION_ERROR", "limit must be a number > 0")

    cache_key = "insect_hotspots|default"

    snaps = _load("fetch_snapshots.json")
    ds_id = ds.get("id")
    fresh = []
    for sn in snaps:
        if sn.get("source_id") != ds_id:
            continue
        if sn.get("cache_key") != cache_key:
            continue
        if sn.get("status") != "fresh":
            continue
        exp = _parse_dt(sn.get("expires_at"))
        if exp is None or exp <= now:
            continue
        fresh.append(sn)
    fresh.sort(key=lambda r: _parse_dt(r.get("fetched_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)

    if not fresh:
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "client_id": client["id"],
            "api_key_id": key["id"],
            "tool_name": "insect-hotspots",
            "request_params": {"limit": limit} if limit is not None else {},
            "limit": float(limit) if limit is not None else None,
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "failed",
            "snapshot_ids": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "UPSTREAM_ERROR",
            "error_message": "No fresh snapshot available",
            "invoked_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _log_invocation(invocations, inv_row)
        return _err("UPSTREAM_ERROR", "Upstream unavailable and no usable cache snapshot")

    snapshot = fresh[0]
    items = snapshot.get("normalized_items") or []
    if not isinstance(items, list):
        items = []
    if eff_limit is not None:
        items = items[:eff_limit]

    keys = _load("api_keys.json")
    changed = False
    for k in keys:
        if k.get("id") == key["id"]:
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            changed = True
            break
    if changed:
        _save("api_keys.json", keys)

    inv_id = _gen_id("inv")
    inv_row = {
        "id": inv_id,
        "client_id": client["id"],
        "api_key_id": key["id"],
        "tool_name": "insect-hotspots",
        "request_params": {"limit": limit} if limit is not None else {},
        "limit": float(limit) if limit is not None else None,
        "horoscope_type": None,
        "horoscope_time": None,
        "sentence_random": None,
        "status": "served_from_cache",
        "snapshot_ids": [snapshot.get("id")],
        "latency_ms": int((time.time() - t0) * 1000),
        "error_code": None,
        "error_message": None,
        "invoked_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    _log_invocation(invocations, inv_row)

    return {
        "tool_name": "insect-hotspots",
        "status": "served_from_cache",
        "data_source": {"id": ds.get("id"), "code": ds.get("code"), "status": ds.get("status")},
        "cache": {"cache_key": cache_key, "snapshot_id": snapshot.get("id"), "fetched_at": snapshot.get("fetched_at"), "expires_at": snapshot.get("expires_at")},
        "effective_limit": eff_limit,
        "items": items,
        "items_count": len(items),
    }

def list_data_sources(api_key, category=None, status=None, code=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _minute_bucket(now_dt):
        return now_dt.strftime("%Y-%m-%dT%H:%M")

    def _day_bucket(now_dt):
        return now_dt.strftime("%Y-%m-%d")

    def _count_usage(invocations, client_id, now_dt):
        minute_key = _minute_bucket(now_dt)
        day_key = _day_bucket(now_dt)
        rpm = 0
        daily = 0
        for r in invocations:
            if r.get("client_id") != client_id:
                continue
            ia = _parse_dt(r.get("invoked_at") or r.get("created_at"))
            if ia is None:
                continue
            if _minute_bucket(ia) == minute_key:
                rpm += 1
            if _day_bucket(ia) == day_key:
                daily += 1
        return rpm, daily

    def _log_invocation(invocations, row):
        invocations.append(row)
        _save("tool_invocations.json", invocations)

    t0 = time.time()
    now = _now_utc()

    # Validate inputs
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string with length >= 8")

    if category is not None:
        if category not in ("hotspots", "horoscope", "sentence"):
            return _err("VALIDATION_ERROR", "category must be one of: hotspots, horoscope, sentence")

    if status is not None:
        if status not in ("enabled", "disabled", "degraded"):
            return _err("VALIDATION_ERROR", "status must be one of: enabled, disabled, degraded")

    if code is not None:
        if not isinstance(code, str) or len(code) < 1:
            return _err("VALIDATION_ERROR", "code must be a non-empty string")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or isinstance(limit, bool):
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    if cursor is not None and not isinstance(cursor, str):
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Authenticate by matching id or key_prefix (client-visible)
    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    invocations = _load("tool_invocations.json")

    key_row = None
    for k in keys:
        if k.get("id") == api_key or k.get("key_prefix") == api_key:
            key_row = k
            break

    if key_row is None:
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "client_id": "unknown",
            "api_key_id": "unknown",
            "tool_name": "list-data-sources",
            "request_params": {"api_key": api_key, **({} if category is None else {"category": category}),
                               **({} if status is None else {"status": status}),
                               **({} if code is None else {"code": code}),
                               "limit": limit, **({} if cursor is None else {"cursor": cursor})},
            "limit": float(limit),
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "failed",
            "snapshot_ids": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "UNAUTHORIZED",
            "error_message": "Invalid API key",
            "invoked_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _log_invocation(invocations, inv_row)
        return _err("UNAUTHORIZED", "Unauthorized")

    client_row = None
    for c in clients:
        if c.get("id") == key_row.get("client_id"):
            client_row = c
            break

    if client_row is None or key_row.get("status") != "active" or client_row.get("status") != "active":
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "client_id": (client_row.get("id") if client_row else (key_row.get("client_id") or "unknown")),
            "api_key_id": key_row.get("id") or "unknown",
            "tool_name": "list-data-sources",
            "request_params": {"api_key": api_key, **({} if category is None else {"category": category}),
                               **({} if status is None else {"status": status}),
                               **({} if code is None else {"code": code}),
                               "limit": limit, **({} if cursor is None else {"cursor": cursor})},
            "limit": float(limit),
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "failed",
            "snapshot_ids": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "UNAUTHORIZED",
            "error_message": "API key or client is not active",
            "invoked_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _log_invocation(invocations, inv_row)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Rate limit/quota
    rpm_limit = client_row.get("rate_limit_rpm")
    daily_quota = client_row.get("daily_quota_requests")
    rpm_used, daily_used = _count_usage(invocations, client_row["id"], now)

    if isinstance(rpm_limit, int) and rpm_limit >= 1 and (rpm_used + 1) > rpm_limit:
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "client_id": client_row["id"],
            "api_key_id": key_row["id"],
            "tool_name": "list-data-sources",
            "request_params": {"api_key": api_key, **({} if category is None else {"category": category}),
                               **({} if status is None else {"status": status}),
                               **({} if code is None else {"code": code}),
                               "limit": limit, **({} if cursor is None else {"cursor": cursor})},
            "limit": float(limit),
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "rate_limited",
            "snapshot_ids": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "RATE_LIMIT",
            "error_message": "Rate limit exceeded",
            "invoked_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _log_invocation(invocations, inv_row)
        return _err("RATE_LIMIT", "Rate limit exceeded", limit_rpm=rpm_limit)

    if isinstance(daily_quota, int) and daily_quota != -1 and (daily_used + 1) > daily_quota:
        inv_id = _gen_id("inv")
        inv_row = {
            "id": inv_id,
            "client_id": client_row["id"],
            "api_key_id": key_row["id"],
            "tool_name": "list-data-sources",
            "request_params": {"api_key": api_key, **({} if category is None else {"category": category}),
                               **({} if status is None else {"status": status}),
                               **({} if code is None else {"code": code}),
                               "limit": limit, **({} if cursor is None else {"cursor": cursor})},
            "limit": float(limit),
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "rate_limited",
            "snapshot_ids": None,
            "latency_ms": int((time.time() - t0) * 1000),
            "error_code": "QUOTA_EXCEEDED",
            "error_message": "Daily quota exceeded",
            "invoked_at": _iso(now),
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        _log_invocation(invocations, inv_row)
        return _err("QUOTA_EXCEEDED", "Daily quota exceeded", daily_quota=daily_quota)

    # Pagination cursor: use integer offset encoded as string "offset:<n>"
    offset = 0
    if cursor:
        if cursor.startswith("offset:"):
            try:
                offset = int(cursor.split(":", 1)[1])
            except Exception:
                return _err("VALIDATION_ERROR", "Invalid cursor")
            if offset < 0:
                return _err("VALIDATION_ERROR", "Invalid cursor")
        else:
            return _err("VALIDATION_ERROR", "Invalid cursor")

    sources = _load("data_sources.json")
    rows = []
    for s in sources:
        if category is not None and s.get("category") != category:
            continue
        if status is not None and s.get("status") != status:
            continue
        if code is not None and s.get("code") != code:
            continue
        rows.append(s)

    # Stable ordering by code then id
    rows.sort(key=lambda r: ((r.get("code") or ""), (r.get("id") or "")))

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = f"offset:{next_offset}" if has_more else None

    # Update api_key last_used_at
    keys2 = _load("api_keys.json")
    changed = False
    for k in keys2:
        if k.get("id") == key_row.get("id"):
            k["last_used_at"] = _iso(now)
            k["updated_at"] = _iso(now)
            changed = True
            break
    if changed:
        _save("api_keys.json", keys2)

    inv_id = _gen_id("inv")
    inv_row = {
        "id": inv_id,
        "client_id": client_row["id"],
        "api_key_id": key_row["id"],
        "tool_name": "list-data-sources",
        "request_params": {"api_key": api_key, **({} if category is None else {"category": category}),
                           **({} if status is None else {"status": status}),
                           **({} if code is None else {"code": code}),
                           "limit": limit, **({} if cursor is None else {"cursor": cursor})},
        "limit": float(limit),
        "horoscope_type": None,
        "horoscope_time": None,
        "sentence_random": None,
        "status": "fetched_live",
        "snapshot_ids": None,
        "latency_ms": int((time.time() - t0) * 1000),
        "error_code": None,
        "error_message": None,
        "invoked_at": _iso(now),
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    _log_invocation(invocations, inv_row)

    return {
        "object": "list",
        "data": page,
        "total": total,
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
    }

def get_data_source(api_key, id, **_extra):
    import json, os, datetime, uuid, time as _time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    TOOL_NAME = "get-data-source"
    t0 = _time.time()

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _dt_parse(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str) or not v.strip():
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _dt_iso(dt):
        if isinstance(dt, str):
            return dt
        if not isinstance(dt, datetime.datetime):
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _gen_id(prefix):
        return f"pulse_{prefix}_{uuid.uuid4().hex}"

    def _inv_base(client_id, api_key_id):
        now = _now_utc()
        return {
            "id": _gen_id("inv"),
            "client_id": client_id,
            "api_key_id": api_key_id,
            "tool_name": TOOL_NAME,
            "request_params": {"api_key": api_key, "id": id},
            "limit": None,
            "horoscope_type": None,
            "horoscope_time": None,
            "sentence_random": None,
            "status": "received",
            "snapshot_ids": None,
            "latency_ms": None,
            "error_code": None,
            "error_message": None,
            "invoked_at": _dt_iso(now),
            "created_at": _dt_iso(now),
            "updated_at": _dt_iso(now),
        }

    if _extra:
        return _err("VALIDATION_ERROR", "Unknown parameters", unknown=list(_extra.keys()))
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string with minLength 8")
    if not isinstance(id, str) or len(id) < 1:
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    api_clients = _load("api_clients.json")
    api_keys = _load("api_keys.json")
    data_sources = _load("data_sources.json")
    invocations = _load("tool_invocations.json")

    client_by_id = {c.get("id"): c for c in api_clients if isinstance(c, dict)}

    # Authenticate: match api_key against api_keys.id OR api_keys.key_prefix (client-visible); never key_hash
    authed_key = None
    authed_client = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if api_key == k.get("id") or api_key == k.get("key_prefix"):
            c = client_by_id.get(k.get("client_id"))
            if k.get("status") == "active" and c and c.get("status") == "active":
                authed_key, authed_client = k, c
                break

    if not authed_key or not authed_client:
        # record failed invocation with placeholders (cannot satisfy FK, but store already contains such patterns)
        inv = _inv_base(client_id="unknown", api_key_id="unknown")
        inv["status"] = "failed"
        inv["error_code"] = "UNAUTHORIZED"
        inv["error_message"] = "Invalid or inactive api_key/client"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("UNAUTHORIZED", "Unauthorized")

    inv = _inv_base(client_id=authed_client["id"], api_key_id=authed_key["id"])

    row = None
    for ds in data_sources:
        if isinstance(ds, dict) and ds.get("id") == id:
            row = ds
            break

    if not row:
        inv["status"] = "failed"
        inv["error_code"] = "NOT_FOUND"
        inv["error_message"] = "Data source not found"
        inv["latency_ms"] = int((_time.time() - t0) * 1000)
        inv["updated_at"] = _dt_iso(_now_utc())
        invocations.append(inv)
        _save("tool_invocations.json", invocations)
        return _err("NOT_FOUND", "Data source not found")

    inv["status"] = "served_from_cache"
    inv["latency_ms"] = int((_time.time() - t0) * 1000)
    inv["updated_at"] = _dt_iso(_now_utc())
    invocations.append(inv)
    _save("tool_invocations.json", invocations)

    authed_key["last_used_at"] = _dt_iso(_now_utc())
    authed_key["updated_at"] = _dt_iso(_now_utc())
    _save("api_keys.json", api_keys)

    return {"data": row}

def update_data_source(api_key, id, status=None, display_name=None, default_limit=None, max_limit=None, cache_ttl_seconds=None, endpoint_url=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0077000" if __import__("os").path.isdir("./environment_mix/0077000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): 
        return {"error": {"code": code, "message": msg, **x}}

    def _now_utc():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or len(api_key) < 8:
        return _err("VALIDATION_ERROR", "api_key must be a string with minLength 8")
    if not isinstance(id, str) or len(id) < 1:
        return _err("VALIDATION_ERROR", "id must be a non-empty string")

    allowed_status = {"enabled", "disabled", "degraded"}
    if status is not None and status not in allowed_status:
        return _err("VALIDATION_ERROR", "Invalid status", allowed=list(allowed_status))

    if display_name is not None and (not isinstance(display_name, str) or len(display_name) < 1):
        return _err("VALIDATION_ERROR", "display_name must be a non-empty string")
    if endpoint_url is not None and (not isinstance(endpoint_url, str) or len(endpoint_url) < 1):
        return _err("VALIDATION_ERROR", "endpoint_url must be a non-empty string")

    for nm, val in [("default_limit", default_limit), ("max_limit", max_limit), ("cache_ttl_seconds", cache_ttl_seconds)]:
        if val is None:
            continue
        if not isinstance(val, int):
            return _err("VALIDATION_ERROR", f"{nm} must be an integer")
        if val < 1:
            return _err("VALIDATION_ERROR", f"{nm} must be >= 1")

    # More constraints for data_sources
    if cache_ttl_seconds is not None and not (5 <= cache_ttl_seconds <= 86400):
        return _err("VALIDATION_ERROR", "cache_ttl_seconds must be between 5 and 86400")

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    inv = _load("tool_invocations.json")
    sources = _load("data_sources.json")

    def _auth_resolve_key(api_key_plain):
        for k in keys:
            if not isinstance(k, dict):
