            if k.get("id") == api_key_plain or k.get("key_prefix") == api_key_plain:
                c = next((cc for cc in clients if isinstance(cc, dict) and cc.get("id") == k.get("client_id")), None)
                if c and k.get("status") == "active" and c.get("status") == "active":
                    return c, k
        return None, None

    client, keyrow = _auth_resolve_key(api_key)

    invoked_at = _now_utc()
    invocation_row = {
        "id": _new_id("inv"),
        "client_id": client["id"] if client else "",
        "api_key_id": keyrow["id"] if keyrow else "",
        "tool_name": "update-data-source",
        "request_params": {
            "id": id,
            **({} if status is None else {"status": status}),
            **({} if display_name is None else {"display_name": display_name}),
            **({} if default_limit is None else {"default_limit": default_limit}),
            **({} if max_limit is None else {"max_limit": max_limit}),
            **({} if cache_ttl_seconds is None else {"cache_ttl_seconds": cache_ttl_seconds}),
            **({} if endpoint_url is None else {"endpoint_url": endpoint_url}),
        },
        "limit": None,
