        "sentence_random": None,
        "status": "received",
        "snapshot_ids": None,
        "latency_ms": None,
        "error_code": None,
        "error_message": None,
        "invoked_at": _iso(invoked_at),
        "created_at": _iso(invoked_at),
        "updated_at": _iso(invoked_at),
    }

    if not client or not keyrow:
        invocation_row["status"] = "failed"
        invocation_row["error_code"] = "UNAUTHORIZED"
        invocation_row["error_message"] = "Invalid or inactive api_key, or client suspended/deleted."
        invocation_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        invocation_row["updated_at"] = _iso(_now_utc())
        inv.append(invocation_row)
        _save("tool_invocations.json", inv)
        return _err("UNAUTHORIZED", "Unauthorized")

    # Update key last_used_at
    for k in keys:
        if isinstance(k, dict) and k.get("id") == keyrow.get("id"):
            k["last_used_at"] = _iso(invoked_at)
            k["updated_at"] = _iso(invoked_at)
            break

    # Rate limit / quota
    def _same_day_local(iso_ts, tzname):
        dt = _parse_dt(iso_ts)
        if not dt:
            return None
        tz = datetime.timezone.utc
        if isinstance(tzname, str):
            s = tzname.strip()
            try:
                if (len(s) == 6 and (s[0] in "+-") and s[3] == ":"):
                    hh = int(s[1:3]); mm = int(s[4:6])
                    off = datetime.timedelta(hours=hh, minutes=mm)
                    if s[0] == "-":
                        off = -off
                    tz = datetime.timezone(off)
            except Exception:
                tz = datetime.timezone.utc
        return dt.astimezone(tz).date()

    def _enforce_limits():
        client_id = client.get("id")
        dq = client.get("daily_quota_requests")
        tzname = client.get("default_timezone") or "UTC"
        if isinstance(dq, int) and dq != -1:
            today_local = _same_day_local(_iso(_now_utc()), tzname)
            count = 0
            for r in inv:
                if not isinstance(r, dict):
                    continue
                if r.get("client_id") != client_id:
                    continue
                d = _same_day_local(r.get("invoked_at"), tzname)
                if d and today_local and d == today_local:
                    count += 1
            if count >= dq:
                return "QUOTA_EXCEEDED", "Daily quota exceeded"

        rpm = client.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 60
        now = _now_utc()
        window_start = now - datetime.timedelta(seconds=60)
        count = 0
        for r in inv:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client.get("id"):
                continue
            dt = _parse_dt(r.get("invoked_at"))
            if dt and dt >= window_start and dt <= now:
                count += 1
        if count >= rpm:
            return "RATE_LIMIT", "Rate limit exceeded"
        return None, None

    code, msg = _enforce_limits()
    if code:
        invocation_row["status"] = "rate_limited"
        invocation_row["error_code"] = code
        invocation_row["error_message"] = msg
        invocation_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        invocation_row["updated_at"] = _iso(_now_utc())
        inv.append(invocation_row)
        _save("tool_invocations.json", inv)
        _save("api_keys.json", keys)
        return _err(code, msg)

    # Find data source
    ds_idx = None
    for i, s in enumerate(sources):
        if isinstance(s, dict) and s.get("id") == id:
            ds_idx = i
            break
    if ds_idx is None:
        invocation_row["status"] = "failed"
        invocation_row["error_code"] = "NOT_FOUND"
        invocation_row["error_message"] = "data_source not found"
        invocation_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        invocation_row["updated_at"] = _iso(_now_utc())
        inv.append(invocation_row)
        _save("tool_invocations.json", inv)
        _save("api_keys.json", keys)
        return _err("NOT_FOUND", "Data source not found", id=id)

    ds = sources[ds_idx]
    before_status = ds.get("status")

    # Enforce lifecycle transitions if status provided
    transitions = {
        "enabled": {"degraded", "disabled"},
        "degraded": {"enabled", "disabled"},
        "disabled": {"enabled"},
    }
    if status is not None:
        if before_status not in transitions:
            invocation_row["status"] = "failed"
            invocation_row["error_code"] = "VALIDATION_ERROR"
            invocation_row["error_message"] = "Current status invalid"
            invocation_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
            invocation_row["updated_at"] = _iso(_now_utc())
            inv.append(invocation_row)
            _save("tool_invocations.json", inv)
            _save("api_keys.json", keys)
            return _err("VALIDATION_ERROR", "Current status invalid", current=before_status)
        if status != before_status and status not in transitions.get(before_status, set()):
            invocation_row["status"] = "failed"
            invocation_row["error_code"] = "INVALID_TRANSITION"
            invocation_row["error_message"] = f"Illegal transition {before_status} -> {status}"
            invocation_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
            invocation_row["updated_at"] = _iso(_now_utc())
            inv.append(invocation_row)
            _save("tool_invocations.json", inv)
            _save("api_keys.json", keys)
            return _err("INVALID_TRANSITION", "Illegal status transition", from_status=before_status, to_status=status)

    # Apply updates + constraints
    new_default = ds.get("default_limit") if default_limit is None else default_limit
    new_max = ds.get("max_limit") if max_limit is None else max_limit
    if new_default is not None and not isinstance(new_default, int):
        return _err("VALIDATION_ERROR", "default_limit must be integer or null")
    if new_max is not None and not isinstance(new_max, int):
        return _err("VALIDATION_ERROR", "max_limit must be integer or null")
    if new_default is not None and new_default < 1:
        return _err("VALIDATION_ERROR", "default_limit must be >= 1")
    if new_max is not None and new_max < 1:
        return _err("VALIDATION_ERROR", "max_limit must be >= 1")
    if new_default is not None and new_max is not None and new_default > new_max:
        return _err("VALIDATION_ERROR", "default_limit must be <= max_limit")

    if display_name is not None:
        ds["display_name"] = display_name
    if endpoint_url is not None:
        ds["endpoint_url"] = endpoint_url
    if default_limit is not None:
        ds["default_limit"] = default_limit
    if max_limit is not None:
        ds["max_limit"] = max_limit
    if cache_ttl_seconds is not None:
        ds["cache_ttl_seconds"] = cache_ttl_seconds
    if status is not None:
        ds["status"] = status

    ds["updated_at"] = _iso(_now_utc())
    sources[ds_idx] = ds
    _save("data_sources.json", sources)

    invocation_row["status"] = "fetched_live"
    invocation_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
    invocation_row["updated_at"] = _iso(_now_utc())
    inv.append(invocation_row)
    _save("tool_invocations.json", inv)
    _save("api_keys.json", keys)

    return {
        "data": ds,
        "meta": {
            "invocation_id": invocation_row["id"],
            "client_id": client["id"],
            "api_key_id": keyrow["id"],
        }
    }

def list_tool_invocations(api_key, client_id=None, api_key_id=None, tool_name=None, status=None, from_invoked_at=None, to_invoked_at=None, limit=None, cursor=None, **_extra):
