    if to_invoked_at is not None and dt_to is None:
        return _err("VALIDATION_ERROR", "to_invoked_at must be ISO-8601 datetime string")
    if dt_from and dt_to and dt_from > dt_to:
        return _err("VALIDATION_ERROR", "from_invoked_at must be <= to_invoked_at")

    clients = _load("api_clients.json")
    keys = _load("api_keys.json")
    inv = _load("tool_invocations.json")

    def _auth_resolve_key(api_key_plain):
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == api_key_plain or k.get("key_prefix") == api_key_plain:
                c = next((cc for cc in clients if isinstance(cc, dict) and cc.get("id") == k.get("client_id")), None)
                if c and k.get("status") == "active" and c.get("status") == "active":
                    return c, k
        return None, None

    client, keyrow = _auth_resolve_key(api_key)

    invoked_at = _now_utc()
    invocation_row = {
        "id": _new_id("inv"),
        "client_id": client["id"] if client else "",
        "api_key_id": keyrow["id"] if keyrow else "",
        "tool_name": "list-tool-invocations",
        "request_params": {
            **({} if client_id is None else {"client_id": client_id}),
            **({} if api_key_id is None else {"api_key_id": api_key_id}),
            **({} if tool_name is None else {"tool_name": tool_name}),
            **({} if status is None else {"status": status}),
            **({} if from_invoked_at is None else {"from_invoked_at": from_invoked_at}),
            **({} if to_invoked_at is None else {"to_invoked_at": to_invoked_at}),
