    # Update key last_used_at
    for k in keys:
        if isinstance(k, dict) and k.get("id") == keyrow.get("id"):
            k["last_used_at"] = _iso(invoked_at)
            k["updated_at"] = _iso(invoked_at)
            break

    # Rate limit / quota
    def _same_day_local(iso_ts, tzname):
        dt = _parse_dt(iso_ts)
        if not dt:
            return None
        tz = datetime.timezone.utc
        if isinstance(tzname, str):
            s = tzname.strip()
            try:
                if (len(s) == 6 and (s[0] in "+-") and s[3] == ":"):
                    hh = int(s[1:3]); mm = int(s[4:6])
                    off = datetime.timedelta(hours=hh, minutes=mm)
                    if s[0] == "-":
                        off = -off
                    tz = datetime.timezone(off)
            except Exception:
                tz = datetime.timezone.utc
        return dt.astimezone(tz).date()

    def _enforce_limits():
        client_id0 = client.get("id")
        dq = client.get("daily_quota_requests")
        tzname = client.get("default_timezone") or "UTC"
        if isinstance(dq, int) and dq != -1:
            today_local = _same_day_local(_iso(_now_utc()), tzname)
            count = 0
            for r in inv:
                if not isinstance(r, dict):
                    continue
                if r.get("client_id") != client_id0:
                    continue
                d = _same_day_local(r.get("invoked_at"), tzname)
                if d and today_local and d == today_local:
                    count += 1
            if count >= dq:
                return "QUOTA_EXCEEDED", "Daily quota exceeded"

        rpm = client.get("rate_limit_rpm")
        if not isinstance(rpm, int) or rpm < 1:
            rpm = 60
        now = _now_utc()
        window_start = now - datetime.timedelta(seconds=60)
        count = 0
        for r in inv:
            if not isinstance(r, dict):
                continue
            if r.get("client_id") != client_id0:
                continue
            dt = _parse_dt(r.get("invoked_at"))
            if dt and dt >= window_start and dt <= now:
                count += 1
        if count >= rpm:
            return "RATE_LIMIT", "Rate limit exceeded"
        return None, None

    code, msg = _enforce_limits()
    if code:
        invocation_row["status"] = "rate_limited"
        invocation_row["error_code"] = code
        invocation_row["error_message"] = msg
        invocation_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
        invocation_row["updated_at"] = _iso(_now_utc())
        inv.append(invocation_row)
        _save("tool_invocations.json", inv)
        _save("api_keys.json", keys)
        return _err(code, msg)

    # Cursor: use offset for simplicity
    cur = _decode_cursor(cursor)
    offset = 0
    if cursor is not None:
        if cur is None or not isinstance(cur, dict) or "offset" not in cur:
            invocation_row["status"] = "failed"
            invocation_row["error_code"] = "VALIDATION_ERROR"
            invocation_row["error_message"] = "Invalid cursor"
            invocation_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
            invocation_row["updated_at"] = _iso(_now_utc())
            inv.append(invocation_row)
            _save("tool_invocations.json", inv)
            _save("api_keys.json", keys)
            return _err("VALIDATION_ERROR", "Invalid cursor")
        if not isinstance(cur["offset"], int) or cur["offset"] < 0:
            invocation_row["status"] = "failed"
            invocation_row["error_code"] = "VALIDATION_ERROR"
            invocation_row["error_message"] = "Invalid cursor offset"
            invocation_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
            invocation_row["updated_at"] = _iso(_now_utc())
            inv.append(invocation_row)
            _save("tool_invocations.json", inv)
            _save("api_keys.json", keys)
            return _err("VALIDATION_ERROR", "Invalid cursor offset")
        offset = cur["offset"]

    # Filter
    rows = []
    for r in inv:
        if not isinstance(r, dict):
            continue
        if client_id is not None and r.get("client_id") != client_id:
            continue
        if api_key_id is not None and r.get("api_key_id") != api_key_id:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if status is not None and r.get("status") != status:
            continue
        dt = _parse_dt(r.get("invoked_at"))
        if dt_from and (dt is None or dt < dt_from):
            continue
        if dt_to and (dt is None or dt > dt_to):
            continue
        rows.append(r)

    # Sort by invoked_at desc then id desc
    def _sort_key(r):
        dt = _parse_dt(r.get("invoked_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return (dt, str(r.get("id") or ""))

    rows.sort(key=_sort_key, reverse=True)

    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _encode_cursor({"offset": next_offset}) if has_more else None

    invocation_row["status"] = "served_from_cache"
    invocation_row["latency_ms"] = max(0, int((time.time() - t0) * 1000))
    invocation_row["updated_at"] = _iso(_now_utc())
    inv.append(invocation_row)
    _save("tool_invocations.json", inv)
    _save("api_keys.json", keys)

    return {
        "data": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "next_cursor": next_cursor,
            "has_more": has_more,
            "invocation_id": invocation_row["id"],
            "client_id": client["id"],
            "api_key_id": keyrow["id"],
